INSERT INTO `chat_logs` VALUES (31,1,1,'customer','Halo, saya mau tanya soal pendaftaran merek dagang',NULL,NULL,'faq','merek_pendaftaran','2026-05-07 01:10:05'),(32,1,1,'ai','Halo! Saya GAVI. Untuk pendaftaran merek dagang, Anda bisa mengajukan melalui aplikasi MEREK.',NULL,87.50,'faq','merek_pendaftaran','2026-05-07 01:10:08'),(33,1,1,'customer','Berapa biaya pendaftaran mereknya?',NULL,NULL,'faq','merek_biaya','2026-05-07 01:11:00'),(34,1,1,'ai','Biaya pendaftaran merek untuk UMKM adalah Rp 500.000 per kelas. Untuk umum Rp 1.800.000 per kelas.',NULL,91.20,'faq','merek_biaya','2026-05-07 01:11:05'),(35,2,2,'customer','Saya perlu informasi tentang pendirian PT',NULL,NULL,'faq','pt_pendirian','2026-05-07 02:30:10'),(36,2,2,'ai','Untuk pendirian PT prosesnya dilakukan melalui sistem AHU Online. Siapkan akta notaris, KTP pendiri, dan NPWP.',NULL,78.30,'faq','pt_pendirian','2026-05-07 02:30:15'),(37,2,2,'customer','Berapa modal minimum untuk PT?',NULL,NULL,'faq','pt_modal','2026-05-07 02:31:00'),(38,2,2,'ai','Maaf, saya tidak memiliki informasi yang akurat. Pertanyaan Anda akan saya eskalasikan ke petugas kami.',NULL,35.00,'ticket','pt_modal','2026-05-07 02:31:08'),(39,3,3,'customer','Hak cipta lagu saya, bagaimana mendaftarkannya?',NULL,NULL,'faq','hak_cipta','2026-05-08 03:15:00'),(40,3,3,'ai','Pendaftaran hak cipta dapat dilakukan melalui e-hakcipta.dgip.go.id. Upload karya dan bayar PNBP.',NULL,89.40,'faq','hak_cipta','2026-05-08 03:15:06'),(41,4,4,'customer','Kami ingin mengajukan bantuan hukum, bagaimana prosedurnya?',NULL,NULL,'faq','bankum_prosedur','2026-05-08 06:45:00'),(42,4,4,'ai','Silakan datang ke Kanwil dengan KTP dan surat keterangan tidak mampu dari kelurahan.',NULL,82.10,'faq','bankum_prosedur','2026-05-08 06:45:05'),(43,4,4,'customer','Apakah bisa secara online?',NULL,NULL,'faq','bankum_online','2026-05-08 06:46:00'),(44,4,4,'ai','Untuk saat ini belum tersedia secara online. Hubungi kami di (0274) 512345.',NULL,72.80,'faq','bankum_online','2026-05-08 06:46:08'),(45,5,5,'customer','Saya mau tanya soal paten produk baru saya',NULL,NULL,'faq','paten_produk','2026-05-09 01:00:00'),(46,5,5,'ai','Untuk paten produk baru, daftar di dgip.go.id. Produk harus baru, mengandung langkah inventif.',NULL,85.60,'faq','paten_produk','2026-05-09 01:00:07'),(47,5,5,'customer','Saya tidak mengerti prosedur teknisnya, bisa dibantu langsung?',NULL,NULL,'ticket','paten_konsultasi','2026-05-09 01:01:00'),(48,5,5,'ai','Tentu, saya akan menghubungkan Anda dengan petugas KI kami.',NULL,42.00,'ticket','paten_konsultasi','2026-05-09 01:01:05'),(49,6,6,'customer','Informasi tentang fidusia online dong',NULL,NULL,'faq','fidusia','2026-05-09 02:20:00'),(50,6,6,'ai','Pendaftaran jaminan fidusia online di fidusia.ahu.go.id. Notaris yang terdaftar dapat langsung mengaksesnya.',NULL,88.90,'faq','fidusia','2026-05-09 02:20:06'),(51,7,7,'customer','Kewarganegaraan ganda untuk anak saya yang lahir di luar negeri',NULL,NULL,'faq','kewarganegaraan','2026-05-09 04:00:00'),(52,7,7,'ai','Diatur dalam UU No. 12 Tahun 2006. Anak berhak mendapat kewarganegaraan ganda hingga usia 21 tahun.',NULL,79.20,'faq','kewarganegaraan','2026-05-09 04:00:08'),(53,7,7,'customer','Bagaimana prosedur melepas kewarganegaraan asingnya?',NULL,NULL,'ticket','kewarganegaraan_lepas','2026-05-09 04:01:00'),(54,7,7,'ai','Prosedur pelepasan kewarganegaraan memerlukan penanganan khusus. Saya eskalasikan ke petugas AHU.',NULL,38.50,'ticket','kewarganegaraan_lepas','2026-05-09 04:01:06'),(55,8,8,'customer','Mau konsultasi soal pendirian yayasan pendidikan',NULL,NULL,'faq','yayasan','2026-05-09 07:30:00'),(56,8,8,'ai','Pendirian yayasan diatur UU No. 16 Tahun 2001. Proses melalui notaris dan AHU Online. Minimal 3 pendiri.',NULL,83.70,'faq','yayasan','2026-05-09 07:30:07'),(57,9,1,'customer','Update soal merek saya, sudah ada kabarnya?',NULL,NULL,'ticket','merek_update','2026-05-10 00:50:00'),(58,9,1,'ai','Saya tidak menemukan data tiket Anda. Bisa ceritakan kembali masalah merek Anda?',NULL,28.00,'ticket','merek_update','2026-05-10 00:50:06'),(59,10,3,'customer','Hak cipta lagu saya sudah terdaftar, sertifikatnya kapan keluar?',NULL,NULL,'ticket','hak_cipta_sertifikat','2026-05-10 02:10:00'),(60,10,3,'ai','Untuk status sertifikat hak cipta, saya sambungkan dengan petugas KI kami.',NULL,31.00,'ticket','hak_cipta_sertifikat','2026-05-10 02:10:05');
