INSERT INTO `knowledge_base` VALUES (1,1,'apa itu merek','*Merek* adalah tanda yang dapat ditampilkan secara grafis berupa gambar, logo, nama, kata, huruf, angka, susunan warna, dalam bentuk 2 (dua) dimensi dan/atau 3 (tiga) dimensi, suara, hologram, atau kombinasi dari 2 (dua) atau lebih unsur tersebut untuk membedakan barang dan/atau jasa yang diproduksi oleh orang atau badan hukum dalam kegiatan perdagangan barang dan/atau jasa.',1,1,'supabase_69ff81e7335e8',NULL,'2026-05-09 18:33:38','2026-05-09 11:50:15'),(2,1,'fungsi pemakaian merek','Pemakaian merek berfungsi sebagai :\\n*1.* Tanda pengenal untuk membedakan hasil produksi yang dihasilkan seseorang atau beberapa orang secara bersama-sama atau badan hukum dengan produksi orang lain atau badan hukum lainnya\\n*2.* Alat promosi, sehingga mempromosikan hasil produksinya cukup dengan menyebut mereknya;\\n*3.* Jaminan atas mutu barang;\\n*4.* Penunjuk asal barang/jasa dihasilkan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(3,1,'merek yang bagaimana yang tidak bisa di daftarkan','*1.* Bertentangan dengan ideologi negara, peraturan perundang-undangan, moralitas, agama, kesusilaan, atau ketertiban umum;\\n*2.* Sama dengan, berkaitan dengan, atau hanya menyebut barang dan/atau jasa yang dimohonkan pendaftarannya;\\n*3.* Memuat unsur yang dapat menyesatkan masyarakat tentang asal, kualitas, jenis, ukuran, macam, tujuan penggunaan barang dan/atau jasa yang dimohonkan pendaftarannya atau merupakan nama varietas tanaman yang dilindungi untuk barang dan/atau jasa yang sejenis;\\n*4.* Memuat keterangan yang tidak sesuai dengan kualitas, manfaat, atau khasiat dari barang dan/atau jasa yang diproduksi;\\n*5.* Tidak memiliki daya pembeda; dan/atau\\n*6* Merupakan nama umum dan/atau lambang milik umum.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(5,1,'jangka waktu merek','Merek terdaftar mendapatkan perlindungan hukum untuk jangka waktu 10 tahun sejak tanggal penerimaan permohonan pendaftaran merek yang bersangkutan dan jangka waktu perlindungan itu dapat diperpanjang.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(6,2,'apa itu paten','Paten adalah hak eksklusif inventor atas invensi di bidang teknologi untuk selama waktu tertentu melaksanakan sendiri atau memberikan persetujuan kepada pihak lain untuk melaksanakan invensinya.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(7,2,'apa itu invensi','Invensi adalah ide inventor yang dituangkan ke dalam suatu kegiatan pemecahan masalah yang spesifik di bidang teknologi, dapat berupa produk atau proses atau penyempurnaan dan pengembangan produk atau proses.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(8,2,'invensi bagaimanakah yang dapat dipatenkan?','*Invensi dapat dipatenkan jika invensi tersebut:\\n*1.* Jika pada saat pengajuan permohonan paten invensi tersebut tidak sama dengan teknologi yang diungkapkan sebelumnya.\\n*2.* Mengandung langkah inventif. Jika invensi tersebut merupakan hal yang tidak dapat diduga sebelumnya bagi seseorang yang mempunyai keahlian tertentu di bidang teknik.\\n*3.* Dapat diterapkan dalam industri. Jika invensi tersebut dapat diproduksi atau dapat digunakan dalam berbagai jenis industri.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(9,2,'berapa lama paten berlaku','*1.* Paten diberikan untuk jangka waktu selama 20 tahun sejak tanggal penerimaan permohonan paten.\\n*2.* Paten sederhana diberikan untuk jangka waktu 10 tahun sejak tanggal penerimaan permohonan paten sederhana.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(10,2,'prosedur pengajuan hak paten','*Berikut Informasi terkait Prosedur Pengajuan Hak Paten :*\\r\\nhttps://drive.google.com/file/d/1jV-bQGhsG98CWWN2JCNV8Dv0hgxwztsn/view?usp=sharing',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(11,3,'apa itu hak cipta','*Hak Cipta* adalah hak eksklusif pencipta yang timbul secara otomatis berdasarkan prinsip deklaratif setelah suatu ciptaan diwujudkan dalam bentuk nyata tanpa mengurangi pembatasan sesuai dengan ketentuan peraturan perundang-undangan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(12,3,'apakah hak terkait itu','Hak terkait adalah hak yang berkaitan dengan hak cipta yang merupakan hak eksklusif bagi pelaku pertunjukan, produser fonogram, atau lembaga penyiaran.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(13,3,'apa saja ciptaan yang dilindungi','Ciptaan yang dilindungi mencakup:\\n*1.* Buku, program komputer, pamflet, perwajahan (lay out) karya tulis yang diterbitkan, dan semua hasil karya tulis lain;\\n*2.* Ceramah, kuliah, pidato, dan ciptaan lain yang sejenis dengan itu;\\n*3.* Alat peraga yang dibuat untuk kepentingan pendidikan dan ilmu pengetahuan;\\n*4.* Lagu atau musik dengan atau tanpa teks;\\n*5.* Drama atau drama musikal, tari, koreografi, pewayangan, dan pantomim;\\n*6.* Seni rupa dalam segala bentuk seperti seni lukis, gambar, seni ukir, seni kaligrafi, seni pahat, seni patung, kolase, dan seni terapan;\\n*7.* Arsitektur;\\n*8.* Peta;\\n*9.* Seni batik;\\n*10.* Fotografi;\\n*11.* Terjemahan, tafsir, saduran, bunga rampai dan karya lain dari hasil pengalihwujudan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(15,4,'apa itu desain industri','*Desain Industri* adalah suatu kreasi tentang bentuk, konfigurasi atau komposisi garis atau warna, atau garis dan warna, atau gabungan daripadanya yang berbentuk tiga dimensi atau dua dimensi yang memberikan kesan estetis dan dapat diwujudkan dalam pola tiga dimensi atau dua dimensi serta dapat dipakai untuk menghasilkan suatu produk, barang, komoditas industri atau kerajinan tangan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(16,4,'desain industri bagaimanakah yang dapat didaftarkan','Desain industri dapat didaftarkan jika desain industri tersebut:\\n*1.* Baru, apabila pada tanggal penerimaan permohonan pendaftaran desain industri tersebut tidak sama dengan pengungkapan desain industri yang telah ada sebelumnya;\\n*2.* Tidak bertentangan dengan peraturan perundang-undangan yang berlaku, ketertiban umum, agama, atau kesusilaan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(17,4,'prosedur pengajuan desain industri','*Adapun Prosedur Pengajuan Desain Industri*\\nhttps://jogja-terpadu.kemenkumham.go.id/kumham/industri.pdf',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(18,5,'apa itu indikasi geografis','*Indikasi Geografis* adalah suatu tanda yang menunjukkan daerah asal suatu barang dan/atau produk yang karena faktor lingkungan geografis termasuk faktor alam, faktor manusia atau kombinasi dari kedua faktor tersebut memberikan reputasi, kualitas, dan karakteristik tertentu pada barang dan/atau produk yang dihasilkan.\\nTanda yang digunakan sebagai indikasi geografis dapat berupa etiket atau label yang dilekatkan pada barang yang dihasilkan. Tanda tersebut dapat berupa nama tempat, daerah, atau wilayah, kata, gambar, huruf, atau kombinasi dari unsur-unsur tersebut.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(19,5,'siapakah yang berhak mengajukan permohonan pendaftaran indikasi geografis','Permohonan pendaftaran indikasi geografis diajukan oleh:\\n*1.* Lembaga yang mewakili masyarakat di kawasan geografis tertentu yang mengusahakan suatu barang dan/atau produk berupa:\\n\\n   A. Sumber daya alam;\\n   B. Barang kerajinan tangan; atau\\n   C. Hasil industri.\\n\\n*2.* Pemerintah daerah provinsi atau kabupaten/kota.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(20,5,'siapakah pemakai indikasi geografis','Pemakai indikasi geografis adalah pihak yang mendapat izin dari pemegang hak atas indikasi geografis yang terdaftar untuk mengolah dan/atau memasarkan barang dan/atau produk indikasi geografis.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(21,5,'prosedur pengajuan indikasi geografis','*Adapun Prosedur Pengajuan Indikasi Geografis*\\nhttps://jogja-terpadu.kemenkumham.go.id/kumham/ig.pdf',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(22,7,'Apakah PT dapat didirikan oleh satu orang?','Berdasarkan Permenkumham Nomor 21 tahun 2021, PT dapat didirikan oleh satu orang namun harus sesuai dengan persyaratan yang berlaku.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(23,7,'Bolehkan kami diberikan penjelasan secara singkat, apa perbedaan antara PT yang selama ini telah ada dengan Perseroan Perorangan ini?','Perseroan Perorangan adalah merupakan salah satu dari bagian dari bentuk Perseroan sesuai ketentuan PP Nomor 8 Tahun 2021 pasal jo Permenkumham Nomor 21 Tahun 2021 pasal 2 ayat (1).\\nPerseroan perorangan merupakan badan hukum perorangan yang memenuhi kriteria untuk usaha mikro dan kecil sebagaimana diatur dalam peraturan perundang-undangan mengenai usaha mikro dan kecil.\\nPerseroan Perorangan didirikan oleh 1 (satu) orang.\\nSedangkan PT yang selama ini sudah ada merupakan Perseroan persekutuan modal yang didirikan berdasarkan perjanjian dan melakukan kegiatan usaha dengan modal dasar yang seluruhnya terbagi dalam saham.\\nPerseroan persekutuan modal didirikan oleh 2 (dua) orang atau lebih.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(24,7,'Peraturan PerUUan apa yang mengatur terkait usaha mikro dan kecil?','Peraturan Perundang-undangan yang mengatur terkait usaha mikro dan kecil diatur didalam Peraturan Pemerintah Nomor 7 Tahun 2021 tentang Kemudahan, Pelindungan, dan Pemberdayaan Koperasi dan Usaha Mikro, Kecil, dan Menengah.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(25,7,'Siapa yang dapat mengajukan pendirian perseroan perorangan?','Yang dapat mendirikan perseroan perorangan adalah Warga Negara Indonesia yang telah memiliki Nomor Induk Kependudukan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(26,7,'Bagaimana cara mendirikan, melakukan perubahan ataupun pembubaran perseroan perorangan?','Pendirian, Perubahan dan Pembubaran Perseroan Perorangan dilakukan secara elektronik tanpa mengggunakan Akta Notaris melainkan dengan pernyataan pendirian, pernyataan Perubahan dan Pernyataan Pembubaran melalui SABH.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(27,7,'Bagaimana bentuk Pernyataan Pendirian yang dimaksud?','Format pernyataan pendirian, perubahan dan pembubaran dapat dilihat dilampiran Peraturan Pemerintah Nomor 8 Tahun 2021 tentang Modal Dasar Perseroan serta Pendaftaran Pendirian, Perubahan, dan Pembubaran Perseroan yang Memenuhi Kriteria untuk Usaha Mikro dan Kecil.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(28,7,'Sejak kapan status badan hukum Perseroan perorangan dapat diperoleh?','Status badan hukum Perseroan perorangan diperoleh sejak keluarnya Sertifikat pendaftaran yang dilakukan melalui SABH pada AHU Online.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(29,7,'Apa Dasar Hukum Perseroan Perorangan?','Dasar hukum Perseroan Perorangan adalah:\\n1. Pasal 109 dan Pasal 185 huruf b Undang-Undang Nomor 11 Tahun 2020 tentang Cipta Kerja;\\n2. Peraturan Pemerintah Republik Indonesia Nomor 8 Tahun 2021 Tentang Modal Dasar Perseroan serta Pendaftaran Pendirian, Perubahan, Dan Pembubaran Perseroan yang Memenuhi Kriteria untuk Usaha Mikro dan Kecil;\\n3. Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 21 Tahun 2021 tentang Syarat dan Tata Cara Pendaftaran Pendirian, Perubahan, dan Pembubaran Badan Hukum Perseroan Terbatas.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(30,7,'Apakah ada kewajiban yang harus dipenuhi setelah memiliki Perseroan Perorangan?','Kewajiban yang harus dipenuhi setelah memiliki Perseroan Perorangan adalah wajib menyampaikan laporan keuangan Perseroan perorangan kepada Menteri dengan melakukan pengisian format isian penyampaian laporan keuangan secara elektronik melalui SABH paling lambat 6 (enam) bulan setelah akhir periode.\\nFormat isian penyampaian laporan keuangan memuat:\\n1. laporan posisi keuangan;\\n2. laporan laba rugi;\\n3. catatan atas laporan keuangan tahun berjalan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(31,7,'Berapa besar biaya mendirikan Perseroan Perorangan?','Berdasarkan Peraturan Menteri Keuangan Republik Indonesia nomor 49/PMK.02/2021 tentang Jenis dan Tarif Atas Jenis Penerimaan Negara Bukan Pajak Yang Berlaku Pada Direktorat Jenderal Administrasi Hukum Umum, Kementerian Hukum dan Hak Asasi Manusia sebagai berikut:\\n1. Pendaftaran Pendirian Perseroan Perorangan untuk Usaha Mikro dan Kecil sebesar 50.000 per permohonan;\\n2. Pendaftaran Perubahan Perseroan Perorangan yang memenuhi Kriteria Usaha Mikro dan Kecil sebesar 50.000 per permohonan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(32,7,'Berapa besar Modal Usaha untuk mendirikan perseroan perorangan?','Besar modal usaha dalam mendirikan Perseroan Perorangan dibagi menjadi 2 kategori modal usaha yakni:\\n1. Usaha Mikro memiliki modal usaha sampai dengan paling banyak Rp1.000.000.000,00 (satu miliar rupiah) tidak termasuk tanah dan bangunan tempat usaha;\\n2. Usaha Kecil memiliki modal usaha lebih dari Rp1.000.000.000,00 (satu miliar rupiah) sampai dengan paling banyak Rp5.000.000.000,00 (lima miliar rupiah) tidak termasuk tanah dan bangunan tempat usaha;\\nKetentuan mengenai kriteria modal usaha mengacu pada Peraturan Pemerintah Nomor 7 Tahun 2021 tentang Kemudahan, Pelindungan, dan Pemberdayaan Koperasi dan Usaha Mikro, Kecil, dan Menengah.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(33,7,'Kapan kah Perseroan Perorangan berubah status menjadi Perseroan Persekutuan Modal?','Berdasarkan Peraturan Menteri Hukum dan Hak Asasi Manusia Nomor 21 Tahun 2021 tentang Syarat dan Tata Cara Pendaftaran Pendirian, Perubahan, dan Pembubaran Badan Hukum Perseroan Terbatas, perseroan perorangan harus mengubah status badan hukumnya menjadi Perseroan persekutuan modal jika:\\n1. pemegang saham menjadi lebih dari 1 (satu) orang;\\n2. tidak memenuhi kriteria usaha mikro dan kecil sebagaimana diatur dalam ketentuan perundang-undangan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(34,7,'Apa saja yang dilakukan untuk proses perubahan status perseroan perorangan menjadi perseroan persekutuan modal?','Yang harus dilakukan adalah:\\n1. Memenuhi kriteria keharusan berubahnya status badan hukum (lihat pasal 17 Permenkumham No 21 Tahun 2021);\\n2. Perseroan perorangan harus melakukan perubahan status tersebut melalui akta notaris dan didaftarkan secara elektronik.\\nAkta notaris yang dimaksud harus memuat:\\n- pernyataan pemegang saham yang memuat perubahan status Perseroan perorangan menjadi Perseroan persekutuan modal;\\n- perubahan anggaran dasar dari semula pernyataan pendirian dan/atau pernyataan perubahan Perseroan perorangan menjadi anggaran dasar;\\n- data Perseroan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(35,8,'Bagaimana cara mendirikan PT?','Menyiapkan nama PT, tempat dan kedudukan PT, maksud dan tujuan PT, struktur permodalan, dan pengurus PT, kemudian melakukan pendirian PT melalui notaris.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(36,8,'Berapa besaran biaya pendirian PT?','Biaya voucher PNBP: Rp300.000 untuk modal di bawah Rp25.000.000; Rp600.000 untuk modal Rp25.000.000–Rp1.000.000.000; Rp1.100.000 untuk modal di atas Rp1.000.000.000.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(37,8,'Berapa lama masa aktif akta pendirian PT?','Sesuai Pasal 10 UU No. 40 Tahun 2007, permohonan pengesahan badan hukum harus diajukan kepada Menteri paling lambat 60 hari sejak tanggal akta pendirian ditandatangani.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(38,8,'Bagaimana tahapan-tahapan verifikasi nama dengan menggunakan voucher satuan?','1. Pengajuan Nama\\n2. Verifikasi sistem (persetujuan menteri)\\n3. Verifikasi oleh verifikator',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(39,8,'Bagaimana untuk PT yang sudah memiliki SK Kemenkumham tapi belum terdaftar di database AHU?','Notaris mengajukan surat permohonan entry data dengan melampirkan:\\n1. Surat pernyataan bermaterai dari notaris bahwa akta adalah akta terakhir yang dicatat dan dilaporkan ke Ditjen AHU dengan nomor pencatatan\\n2. Salinan akta pendirian/fotokopi akta (legalisir notaris)\\n3. Fotokopi SK Pendirian (legalisir notaris)\\n4. Fotokopi Surat Pemberitahuan/SK persetujuan perubahan anggaran dasar (legalisir notaris)\\nSurat permohonan dikirim via pos ke Ditjen AHU, c.q. Subdit Badan Hukum (PT).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(40,8,'Bagaimana prosedur untuk proses penyesuaian CV menjadi PT?','1. Menyelesaikan perikatan antara pengurus CV dan pihak ketiga\\n2. Menyesuaikan Anggaran Dasar CV untuk memenuhi ketentuan modal dasar, ditempatkan, dan disetor PT (Pasal 7 ayat [2] UUPT)\\n3. Membuat akta pendirian PT yang memuat Anggaran Dasar (Pasal 7 ayat [1] jo. Pasal 8 ayat [1] UUPT)\\n4. Pendiri mengajukan pengesahan badan hukum via AHU Online\\n5. Pengumuman di Tambahan Berita Negara RI\\n6. Jika mengikutsertakan perbuatan hukum CV, RUPS pertama harus menyatakan menerima semua hak dan kewajiban (Pasal 13 ayat [1] UUPT)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(41,8,'Berapa besaran modal untuk mendirikan PT?','Berdasarkan Pasal 3 PP No. 8 Tahun 2021, besaran modal dasar PT ditentukan berdasarkan keputusan pendiri perseroan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(42,8,'Berapa besaran jumlah modal yang harus ditempatkan dan disetor?','Berdasarkan Pasal 4 PP No. 8 Tahun 2021, modal dasar PT harus ditempatkan dan disetor penuh minimal 25%, dibuktikan dengan bukti penyetoran, dan disampaikan secara elektronik kepada Menteri dalam waktu paling lama 60 hari sejak tanggal akta pendirian.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(43,8,'Apakah syarat menjadi pemegang saham PT?','Pemegang saham PT harus orang pribadi atau badan hukum yang mampu melakukan perbuatan hukum, wajib pajak, dan Warga Negara Indonesia (WNI).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(44,8,'Apakah Warga Negara Asing atau badan hukum asing bisa menjadi pemegang saham PT?','WNA atau badan hukum asing dapat menjadi pemegang saham PT, tetapi PT akan berstatus PT Penanaman Modal Asing (PMA) dan tunduk pada UU Penanaman Modal Asing.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(45,8,'Apakah syarat dan ketentuan pengajuan nama PT?','Pengajuan nama PT diatur dalam Pasal 5 PP No. 43 Tahun 2011 tentang Tata Cara Pengajuan dan Pemakaian Nama Perseroan Terbatas.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(46,8,'Apakah bidang usaha bisa lebih dari satu?','Bidang usaha harus merujuk pada Klasifikasi Besar Lapangan Usaha Indonesia (KBLI) dan maksimal 5 digit bidang KBLI.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(47,8,'Kenapa Sistem tidak dapat mengakomodir jabatan pengurus seperti Wakil Presiden Direktur, CEO, Wakil Direktur Utama, atau pun jabatan lain?','AHU Online mengacu pada UU PT, sehingga sistem belum mengakomodir jabatan yang tidak termasuk dalam UU PT.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(48,8,'Bagaimana dengan kendala gagal terbitnya NPWP setelah SK Pengesahan keluar?','Gagal terbitnya NPWP disebabkan perbedaan database antara AHU dan DJP. Hubungi KPP Domisili Perseroan hingga sinkronisasi data selesai.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(49,8,'Apa saja perubahan yang termasuk perubahan persetujuan anggaran dasar PT?','Perubahan Persetujuan Anggaran Dasar meliputi:\\n1. Nama\\n2. Tempat Kedudukan\\n3. Maksud dan Tujuan serta Kegiatan\\n4. Jangka Waktu\\n5. Peningkatan Modal Dasar\\n6. Pengurangan Modal Dasar\\n7. Pengurangan Modal ditempatkan dan disetor\\n8. Status Perseroan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(50,8,'Apa saja perubahan yang termasuk perubahan pemberitahuan anggaran dasar PT?','Perubahan Pemberitahuan Anggaran Dasar meliputi:\\n1. Peningkatan Modal ditempatkan/disetor\\n2. Jenis Perseroan\\n3. Perubahan pasal atau ayat lain, seperti Pasal 1 ayat 1, Pasal 1 ayat 2, Pasal 4 ayat 1, Pasal 4 ayat 2, dan pasal lainnya',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(51,8,'Bagaimana prosedur perubahan maksud dan tujuan pada PT?','Mengadakan Rapat Umum Pemegang Saham (RUPS), mencatatkan perubahan dalam akta, lalu memesan voucher persetujuan perubahan anggaran dasar untuk mengakses perubahan di database Ditjen AHU.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(52,8,'Apa yang harus dilakukan jika salah satu pemegang saham PT di Indonesia adalah badan hukum luar negeri dan sudah melakukan pembubaran tanpa sepengetahuan PT tersebut?','Mengadakan perubahan pemegang saham dengan menghadirkan perwakilan badan hukum luar negeri untuk mengalihkan sahamnya ke badan hukum lain atau perorangan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(53,8,'Apakah perbedaan dari akuisisi dan peralihan saham serta merger?','Merger (Pasal 1 ayat [9] UUPT): Perseroan menggabungkan diri ke perseroan lain, aktiva dan pasiva beralih, status badan hukum perseroan yang menggabungkan diri berakhir.\\nAkuisisi (Pasal 1 ayat [11] UUPT): Pengambilalihan saham yang menyebabkan beralihnya pengendalian, badan hukum perseroan tetap ada.\\nPerbedaan:\\n1. Status Badan Hukum: Merger menghentikan badan hukum yang menggabungkan diri; akuisisi tidak.\\n2. Perseroan yang eksis: Merger hanya perseroan pengambil alih; akuisisi kedua perseroan tetap eksis.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(54,8,'Bagaimana solusi terkait dengan KSWP dan NPWP yang tidak valid?','Kendala NPWP tidak valid harus dikonfirmasi ke Ditjen Pajak (DJP). Jika akses terkendala, arahkan ke DJP dan konfirmasi ke TI pusat DJP. Ditjen AHU hanya terintegrasi untuk membaca sistem DJP.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(55,8,'Apakah fitur peleburan sudah ada di dalam SABH?','Fitur peleburan sudah ada di SABH dan dapat diakses seperti pendirian baru hasil peleburan beberapa PT.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(56,8,'Bagaimana dengan kolom NPWP Perseroan yang masih kosong di sistem AHU, apakah saat Perubahan, selama KSWP Valid, bisa diinput kemudian melanjutkan Perubahan?','Selama KSWP valid, NPWP kosong dapat dilanjutkan untuk perubahan tanpa perbaikan ke Badan Hukum. Jika KSWP tidak valid, perubahan tidak dapat dilakukan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(57,8,'Bagaimana dengan kendala NPWP tidak valid saat akses Perubahan?','Ketidakvalidan NPWP disebabkan:\\n1. Nama dan nomor NPWP tidak sesuai\\n2. Belum melaporkan SPT 2 tahun terakhir atau kewajiban pajak lainnya\\nJika masih terkendala, hubungi KPP Domisili Perseroan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(58,8,'Apa prosedur persyaratan pembubaran PT Tahap II?','1. Surat hasil likuidasi dari likuidator kepada Kemenkumham c.q. Direktur Perdata Ditjen AHU beserta rincian pembagian pembebasan harta kekayaan/neraca\\n2. Salinan akta notaris berakhirnya status badan hukum dan pemberitahuan pembebasan tanggung jawab likuidator\\n3. Asli pengumuman di surat kabar sesuai Pasal 152 ayat (3) UU No. 40 Tahun 2007\\n4. Asli bukti PNBP pengumuman di BNRI sebesar Rp30.000 ke rekening 8920247 Perum Percetakan Negara RI\\n5. Surat permohonan notaris, dikirim manual via pos ke Ditjen AHU, Subdit Badan Hukum (PT)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(59,8,'Apakah langkah selanjutnya setelah suatu PT melakukan pembubaran?','Langkah selanjutnya adalah mengakhiri status badan hukum PT dan mengumumkan berakhirnya status badan hukum di Berita Negara RI untuk membebaskan PT dari kewajiban pajak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(60,8,'Bagaimana tata cara mengajukan permohonan pembubaran PT yang telah bubar karena pailit harta atau insolven berdasarkan Putusan Pengadilan Niaga?','1. Sesuai Permenkumham No. 1 Tahun 2016, permohonan pembubaran diajukan notaris via SABH melalui AHU Online\\n2. Setelah Penetapan Pengadilan Negeri, likuidator menghubungi notaris untuk membuat Akta Pembubaran, diakses via AHU Online, dan mengumumkan di media cetak\\n3. Dalam 30 hari setelah Penetapan Pengadilan, lampirkan pengumuman koran, Surat Pemberitahuan online (2 bulan setelah pengumuman), dan bukti PNBP Rp30.000 ke rekening 8920247\\n4. Setelah 60 hari, likuidator melakukan pemberesan, mengumumkan di media, dan meminta notaris membuat Akta Pemberesan\\n5. Tahapan Pembubaran:\\n   a. Tahap I: Notaris akses pemberitahuan pembubaran via AHU Online (akta pembubaran, masuk sistem, jangka waktu 30 hari, menunggu 60 hari untuk SP)\\n   b. Tahap II: Likuidator/Notaris (manual) melakukan pemberesan kekayaan, pengumuman di surat kabar, membuat Akta Pemberesan, melaporkan hasil akhir ke Kemenkumham\\n   c. Pemberitahuan hasil akhir likuidator secara manual ke Kemenkumham\\n   d. Pengumuman berakhirnya status badan hukum PT',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(61,8,'Bagaimana prosedur permohonan salinan SK/SP PT?','Persyaratan permohonan salinan SK/SP:\\n1. Surat permohonan ditujukan ke Direktur Perdata, c.q. Subdit Badan Hukum, Jl. HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan 12940, perihal permohonan salinan/duplikat SK/SP\\n2. Surat kehilangan dari kepolisian, pelaporan oleh Direktur Utama\\n3. Fotokopi akta (legalisir)\\n4. Fotokopi SK/SP yang hilang/rusak (jika ada)\\n5. Fotokopi TBNRI (jika ada)\\n6. Print out voucher PNBP salinan SK/SP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(62,8,'Bagaimana prosedur perbaikan data perseroan yang salah?','Perbaikan data perseroan dilakukan dengan 2 cara:\\n1. Online, jika SK/SP belum lebih dari 90 hari, untuk perbaikan NIK/paspor, NPWP, jabatan sesuai akta\\n2. Manual, jika lebih dari 90 hari\\nPersyaratan perbaikan manual:\\n1. Surat permohonan perihal perbaikan isian database ke Ditjen AHU, c.q. Subdit Badan Hukum, Jl. HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan 12940\\n2. Surat pernyataan bermaterai dari notaris\\n3. Data pendukung:\\n   a. Fotokopi KTP, NPWP, atau paspor (untuk perbaikan KTP, NPWP, paspor)\\n   b. Fotokopi akta (legalisir) untuk perbaikan modal\\n   c. Fotokopi SK/SP perubahan terakhir\\n   d. PNBP perbaikan isian data',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(63,8,'Bagaimana cara perbaikan akta yang sudah diupload?','Akta yang sudah diupload tidak dapat diperbaiki.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(64,8,'Bagaimana terkait kendala Data PT yang terakhir belum terupdate di OSS?','Konfirmasi ke BKPM pusat untuk tarik data manual dengan membawa hasil unduh data profil terakhir.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(65,31,'Apa saja syarat PPKJN (Pelatihan Peningkatan Kualitas Jabatan Notaris)?','A. Syarat Umum:\\n1. Warga Negara Indonesia\\n2. Berusia 27 tahun sebelum pendaftaran PPKJN\\n3. Berijazah Sarjana Hukum dan Strata Dua (M.Kn, SPN, CN)\\n4. Sudah melaksanakan magang di kantor Notaris minimal 24 bulan berturut-turut, diketahui oleh Organisasi (Pengda)\\n5. Tidak berstatus tersangka atau terdakwa atas tindak pidana\\nB. Syarat Pendukung:\\n1. Pasfoto 3x4\\n2. Kartu Tanda Penduduk\\n3. Ijazah Sarjana Hukum dan Strata Dua (M.Kn, SPN, CN)\\n4. Sertifikat Kode Etik dari Organisasi Notaris\\n5. Surat Keterangan Magang 2 tahun di kantor Notaris, diketahui oleh Organisasi Notaris dengan cap\\n6. Surat pernyataan bermaterai Rp10.000 bahwa tidak berstatus tersangka/terdakwa\\n7. Surat pernyataan bermaterai Rp10.000 bahwa semua dokumen yang diunggah benar',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(66,31,'Apa saja dokumen yang harus dilampirkan untuk Pengangkatan Notaris?','A. Dokumen Utama:\\n1. Fotokopi KTP\\n2. Fotokopi Akta Lahir\\n3. Surat Keterangan Sehat Jasmani\\n4. Surat Keterangan Sehat Rohani\\n5. Ijazah S1, S2, Magister Kenotariatan\\n6. Surat Keterangan Magang\\n7. Surat pernyataan tidak rangkap jabatan\\n8. SKCK\\nB. Dokumen Pendukung:\\n1. Fotokopi Sertifikat PPKJN\\n2. Fotokopi Sertifikat Kode Etik\\n3. Surat pernyataan Kesediaan menjadi Pemegang Protokol Notaris\\n4. Fotokopi NPWP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(67,31,'Tata Cara Pengangkatan Notaris?','1. Pengumuman pendaftaran pengangkatan Notaris serentak melalui website Ditjen AHU\\n   a. Membayar biaya akses Rp200.000\\n   b. Mengakses AHU Online untuk mengisi format isian selama 14 hari\\n   c. Memilih wilayah formasi jabatan Notaris, jika tidak ada formasi masuk daftar tunggu, jika ada kirim berkas ke Kantor Pelayanan Cikini\\n2. Berkas dikirim paling lambat 20 hari sejak hari terakhir pengisian format isian\\n3. Verifikasi berkas dalam 20 hari\\n4. Jika diterima, bayar PNBP Pengangkatan Rp1.000.000 dalam 7 hari\\n5. SK Pengangkatan terbit secara elektronik\\n6. Sumpah Jabatan Notaris dalam 60 hari sejak SK terbit, bayar PNBP Rp2.500.000\\n7. Jika lewat 60 hari, SK Pembatalkan diterbitkan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(68,31,'Akses Pengangkatan dan Perpindahan Notaris?','Akses Pengangkatan:\\n1. Masuk ke http://ahu.go.id\\n2. Klik menu pendaftaran Notaris\\n3. Klik Menu daftar\\n4. Pemohon mendapatkan voucher biaya akses permohonan pengangkatan\\nAkses Perpindahan:\\n1. Masuk ke http://ahu.go.id\\n2. Masuk ke akun notaris, akses menu perpindahan notaris\\n3. Pemohon mendapatkan voucher biaya akses permohonan pengangkatan\\nAlternatif: Permohonan biaya akses pengangkatan/perpindahan dilakukan via menu SIMPADU',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(69,31,'Apa saja langkah untuk Daftar Tunggu Pengangkatan Notaris?','Pengisian formulir:\\n1. Nama pemohon\\n2. Tanggal lahir\\n3. Cetak SK tempat kedudukan yang dimohonkan\\n4. Tanggal ijazah strata dua kenotariatan\\n5. Tanggal mulai dan berakhirnya magang',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(70,31,'Permohonan Pindah Wilayah Notaris?','Syarat Pindah:\\n1. Sudah melaksanakan tugas jabatan di Kabupaten/Kota tertentu selama 3 tahun berturut-turut, tidak termasuk cuti\\n2. Dokumen Pendukung:\\n   a. Fotokopi SK Pengangkatan (legalisasi)\\n   b. Fotokopi BAS Jabatan (legalisasi)\\n   c. Asli Surat Keterangan konduite dari MPD, MPW, atau MPP\\n   d. Asli Surat Keterangan cuti dari MPD, MPW, atau MPP\\n   e. Fotokopi sertifikat cuti\\n   f. Asli surat rekomendasi dari Pengurus Daerah, Wilayah, dan Pusat Organisasi Notaris\\n   g. Asli Surat Keterangan dari MPD bahwa Notaris telah menyelesaikan kewajiban\\n   h. Asli surat penunjukan Notaris lain dari MPD',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(71,31,'Apa saja langkah Daftar Tunggu Pindah Wilayah Notaris?','Pengisian Formulir:\\n1. Nama pemohon\\n2. Tanggal lahir\\n3. Cetak SK tempat kedudukan yang dimohonkan\\n4. Tanggal ijazah strata dua kenotariatan\\n5. Berita acara Sumpah Pengangkatan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(72,31,'Syarat dan aktivasi akun Notaris?','Syarat Aktivasi Akun:\\n1. Fotokopi keputusan pengangkatan/perpindahan (legalisasi)\\n2. Fotokopi BAS/janji jabatan Notaris (legalisasi)\\n3. Contoh tanda tangan, paraf, cap/stempel jabatan Notaris (merah) dan alamat kantor\\n4. Fotokopi tanda pemberitahuan penerimaan registrasi GRIPS dari PPATK\\nAlur Aktivasi Akun:\\n1. Mengajukan permohonan aktivasi pada akun Notaris\\n2. Mengirimkan dokumen persyaratan ke Kantor Ditjen AHU\\n3. Jika data lengkap, berkas diverifikasi, status berubah menjadi Notaris (aktif) dan dapat menggunakan layanan AHU',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(73,31,'Bagaimana cara mendapatkan salinan SK notaris?','A. Salinan SK Pengangkatan Notaris:\\n1. Surat permohonan dari Notaris\\n2. Surat keterangan kehilangan dari kepolisian\\n3. Fotokopi SK Pengangkatan\\n4. Bukti pembayaran PNBP Salinan SK\\nB. Salinan SK Perpindahan Notaris:\\n1. Surat permohonan dari Notaris\\n2. Surat keterangan kehilangan dari kepolisian\\n3. Fotokopi SK Perpindahan\\n4. Bukti pembayaran PNBP Salinan SK',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(74,31,'Permohonan Pemberhentian Notaris?','A. Usia pensiun 65/67 tahun:\\n1. Minimal 180 hari/maksimal 60 hari sebelum usia 65/67 tahun\\n2. Mengajukan permohonan pemberhentian di akun Notaris\\n3. Mengirimkan berkas persyaratan\\n4. Verifikasi berkas\\n5. Jika lengkap, terbit SK Pemberhentian\\n6. Jika tidak lengkap, Notaris dihubungi\\nB. Meninggal Dunia:\\n1. Diajukan oleh ahli waris, karyawan Notaris, rekan Notaris/MPD\\n2. Fotokopi akta kematian/surat keterangan kematian (legalisasi)\\n3. Mengajukan permohonan di akun Notaris\\n4. Verifikasi berkas\\n5. Jika lengkap, terbit SK Pemberhentian\\n6. Jika tidak lengkap, dihubungi\\nC. Permintaan Sendiri:\\n1. Mengajukan permohonan di akun Notaris\\n2. Mengirimkan berkas\\n3. Verifikasi berkas\\n4. Jika lengkap, terbit SK Pemberhentian\\n5. Jika tidak lengkap, dihubungi\\nD. Tidak Mampu secara Jasmani/Rohani:\\n1. Mengajukan permohonan di akun Notaris\\n2. Surat keterangan dokter rumah sakit\\n3. Mengirimkan berkas\\n4. Verifikasi berkas\\n5. Jika lengkap, terbit SK Pemberhentian\\n6. Jika tidak lengkap, dihubungi\\nE. Merangkap Jabatan yang dilarang UUJN:\\n1. Mengajukan permohonan di akun Notaris\\n2. Keputusan pengangkatan sebagai PNS, Advokat/jabatan lain (legalisasi)\\n3. Mengirimkan berkas\\n4. Verifikasi berkas\\n5. Jika lengkap, terbit SK Pemberhentian\\n6. Jika tidak lengkap, dihubungi',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(75,31,'Permohonan Pemberhentian Notaris (Pemberhentian Tidak dengan Hormat & Pemberhentian Sementara)?','Syarat Pemberhentian Tidak Hormat dan Sementara:\\n1. Surat usulan pemberhentian Notaris\\n2. Salinan Putusan MPP\\n3. Surat Penunjukan Pemegang Protokol Notaris dari MPD\\nAlur Pemberhentian:\\n1. MPP mengajukan usulan ke Menteri (paling lambat 30 hari sejak putusan diucapkan)\\n2. Verifikasi berkas\\n3. Terbit SK Pemberhentian',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(76,31,'Apa saja tahapan untuk perpanjangan masa Jabatan Notaris?','Permohonan perpanjangan minimal 180 hari/maksimal 60 hari sebelum usia 65 tahun:\\n1. Mengajukan permohonan pada akun Notaris\\n2. Mengirimkan berkas persyaratan\\n3. Verifikasi berkas\\n4. Jika lengkap, wawancara dengan Direktur Perdata\\n5. Jika lolos, bayar PNBP (Kategori A: Rp25.000.000, Kategori B: Rp25.000.000, Kategori C: Rp15.000.000)\\n6. Terbit SK Perpanjangan Masa Jabatan\\n7. Jika tidak lolos wawancara, gugur\\n8. Jika data tidak lengkap, Notaris dihubungi',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(77,31,'Bagaimana alur permohonan Sertifikat Cuti?','1. Mengajukan permohonan Sertifikat Cuti pada akun Notaris\\n2. Membayar PNBP Rp250.000 (paling lambat 7 hari sejak permohonan online)\\n3. Verifikasi berkas\\n4. Sertifikat elektronik dapat dicetak melalui akun Notaris',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(78,31,'Apa saja syarat untuk Perubahan Data Notaris untuk Perubahan Nama?','1. Fotokopi Akta Kelahiran (legalisasi)\\n2. Fotokopi keputusan pengangkatan/perpindahan Notaris (legalisasi)\\n3. Fotokopi salinan Penetapan Pengadilan Negeri (legalisasi), kecuali nama tambahan tertera dalam akta kelahiran\\n4. Fotokopi BAS/janji jabatan Notaris (legalisasi)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(79,31,'Apa saja syarat untuk Perubahan Data Notaris untuk Penambahan Gelar Akademik?','1. Fotokopi Ijazah gelar akademik (legalisasi)\\n2. Fotokopi keputusan pengangkatan/perpindahan Notaris (legalisasi)\\n3. Fotokopi BAS/janji jabatan Notaris (legalisasi)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(80,31,'Apa saja syarat untuk Perubahan Data Notaris untuk Penambahan Gelar Non-Akademik?','1. Fotokopi keputusan pengangkatan/perpindahan Notaris (legalisasi)\\n2. Bukti penambahan gelar non-akademik, diketahui oleh Kepala Desa/Lurah, Camat/pejabat berwenang',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(81,31,'Surat Keterangan MPPN?','A. Syarat Keterangan Konduite:\\n1. Surat permohonan ke Ketua MPPN\\n2. SK Menteri\\n3. Berita Acara Sumpah\\n4. Foto 4x6 (2 lembar)\\n5. Surat Keterangan Konduite Baik dari MPD\\n6. Surat Keterangan jumlah akta dari MPD\\n7. Surat Keterangan belum pernah cuti dari MPD\\n8. Surat Keterangan telah menyelesaikan kewajiban dari MPD\\n9. Surat Keterangan Pemegang Protokol Notaris dari MPD\\n10. Surat Keterangan Konduite Baik dari MPW\\nB. Syarat Rekomendasi Perpanjangan Masa Jabatan ke MPPN:\\n1. Surat permohonan ke Hawkins ke Ketua MPPN\\n2. Fotokopi SK\\n3. Fotokopi Berita Acara Sumpah\\n4. Fotokopi Surat Keterangan Sehat Jasmani\\n5. Fotokopi Surat Keterangan Sehat Rohani\\n6. Rekomendasi dari MPD\\n7. Rekomendasi dari MPW',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(82,31,'Majelis Pengawas Notaris?','1. Laporan pengaduan masyarakat atas dugaan pelanggaran jabatan Notaris disampaikan ke MPD sesuai kedudukan Notaris\\n2. Pemeriksaan dilakukan berjenjang mulai MPD, MPW, hingga upaya hukum banding ke MPP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(83,10,'Apa yang menjadi dasar hukum terkait tata cara pendirian yayasan?','Peraturan Menteri Hukum Dan Hak Asasi Manusia Nomor 2 Tahun 2016 Tentang Tata Cara Pengajuan Permohonan Pengesahan Badan Hukum Dan Persetujuan Perubahan Anggaran Dasar Serta Penyampaian Pemberitahuan Perubahan Anggaran Dasar Dan Perubahan Data Yayasan jo Permenkumham Nomor 13 Tahun 2019',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(84,10,'Apa yang menjadi dasar hukum terkait pemesanan yayasan?','PP Nomor 63 Tahun 2008 jo Permenkumham Nomor 13 Tahun 2019',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(85,10,'Apa saja persyaratan dokumen yang harus dimiliki untuk pendirian yayasan?','Sesuai Pasal 13 Permenkumham Nomor 2 Tahun 2016:\\n1. Salinan akta pendirian Yayasan\\n2. Surat pernyataan tempat kedudukan disertai alamat lengkap Yayasan, ditandatangani oleh pengurus dan diketahui oleh lurah/kepala desa setempat\\n3. Bukti penyetoran atau keterangan bank atas nama Yayasan atau pernyataan tertulis dari pendiri mengenai nilai kekayaan awal\\n4. Surat pernyataan pendiri mengenai keabsahan kekayaan awal\\n5. Bukti penyetoran biaya persetujuan pemakaian nama, pengesahan, dan pengumuman Yayasan\\n6. Surat pernyataan tidak sedang dalam sengketa kepengurusan atau perkara di pengadilan\\n7. Surat pernyataan kesanggupan pendiri untuk memperoleh kartu nomor pokok wajib pajak dan laporan penerimaan surat pemberitahuan tahunan pajak',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(86,10,'Berapa lama proses verifikasi pemesanan nama yayasan?','Proses verifikasi 14 hari kerja, karena banyaknya permohonan dan pemeriksaan dilakukan dengan prinsip kehati-hatian sesuai aturan yang berlaku',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(87,10,'Berapa lama masa aktif akta pendirian yayasan?','Sesuai Pasal 11 UU 28 Tahun 2004, Notaris wajib menyampaikan permohonan pengesahan kepada Menteri dalam waktu paling lambat 10 hari sejak tanggal akta pendirian Yayasan ditandatangani',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(88,10,'Bagaimana persyaratan pendirian yayasan yang didirikan sebelum UU yayasan?','Yayasan yang lahir sebelum Undang-Undang dan tidak memenuhi Pasal 71 UU Yayasan harus melakukan pengesahan pendirian dengan menyebutkan sejarah dalam premisnya sesuai Pasal 15a PP 2 Tahun 2013, dengan terlebih dahulu melakukan pemesanan nama',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(89,10,'Apa saja perubahan yang termasuk persetujuan perubahan anggaran dasar yayasan?','Sesuai Pasal 21 UU 16 Tahun 2001 jo Pasal 18 Permenkumham Nomor 2 Tahun 2016, perubahan anggaran dasar meliputi perubahan nama dan/atau kegiatan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(90,10,'Berapa besaran PNBP persetujuan perubahan anggaran dasar?','Berdasarkan PP Nomor 28 Tahun 2019, PNBP untuk permohonan persetujuan anggaran dasar Yayasan sebesar Rp 250.000',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(91,10,'Apa saja perubahan yang termasuk perubahan pemberitahuan anggaran dasar yayasan?','Sesuai Pasal 24 Permenkumham Nomor 2 Tahun 2016, pemberitahuan anggaran dasar meliputi perubahan selain nama dan/atau kegiatan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(92,10,'Berapa besaran PNBP pemberitahuan perubahan anggaran dasar?','Berdasarkan PP Nomor 28 Tahun 2019, PNBP untuk permohonan pemberitahuan anggaran dasar Yayasan sebesar Rp 100.000',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(93,10,'Bagaimana persyaratan pencatatan pendaftaran Yayasan yang lahir sebelum Undang-Undang?','Yayasan yang lahir sebelum UU Yayasan dan memenuhi Pasal 71 UU Yayasan dapat melakukan penyesuaian sesuai Pasal 37a PP Nomor 2 Tahun 2013, dengan pemesanan nama terlebih dahulu, dan persyaratan sesuai Pasal 37a ayat (4) PP 2 Tahun 2013',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(94,10,'Apa saja perubahan yang termasuk pemberitahuan perubahan data yayasan?','Sesuai Pasal 27 Permenkumham Nomor 2 Tahun 2016, pemberitahuan perubahan data yayasan meliputi perubahan pembina, pengurus, pengawas, dan/atau alamat lengkap',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(95,10,'Berapa besaran PNBP pemberitahuan perubahan data?','Berdasarkan PP Nomor 28 Tahun 2019, PNBP untuk permohonan pemberitahuan data Yayasan sebesar Rp 100.000',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(96,10,'Bagaimana tata cara perubahan Yayasan jika terjadi kekosongan pembina?','Sesuai Pasal 28 ayat (4) Permenkumham Nomor 2 Tahun 2016, jika tidak ada pembina, dalam 30 hari dilakukan rapat gabungan pengurus dan pengawas untuk mengangkat pembina. Setelah pembina baru terbentuk, rapat pembina menentukan agenda lain',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(97,10,'Bagaimana tahapan pembubaran/berakhirnya status badan hukum yayasan?','Sesuai Peraturan Menteri Hukum Dan Hak Asasi Manusia Nomor 18 Tahun 2017 Tentang Tata Cara Pengajuan Permohonan Penggabungan Dan Pemberitahuan Berakhirnya Status Badan Hukum Yayasan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(98,10,'Bagaimana prosedur permohonan salinan SK/SP yayasan?','Persyaratan permohonan salinan SK/SP sesuai Permenkumham Nomor 11 Tahun 2019:\\n1. Surat permohonan ditujukan kepada Direktur Perdata, c.q. Subdit Badan Hukum, Jl. HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan 12940, perihal permohonan salinan/duplikat SK/SP\\n2. Surat keterangan kehilangan dari Kepolisian, dilaporkan oleh ketua pengurus\\n3. Fotokopi akta (legalisir)\\n4. Fotokopi SK/SP yang hilang atau rusak (jika ada)\\n5. Print out voucher PNBP salinan SK/SP\\n6. Surat pernyataan bahwa data sesuai perundang-undangan dan pemohon bertanggung jawab penuh\\n7. Bukti bayar PNBP\\nPermohonan diajukan kepada Menteri melalui Direktur Jenderal, memuat nama badan hukum Yayasan, nomor/tanggal SK, dan nama pengurus Yayasan yang tercatat dalam SABH',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(99,11,'Apa yang menjadi dasar hukum terkait tata cara pendirian perkumpulan?','Peraturan Menteri Hukum Dan Hak Asasi Manusia Nomor 3 Tahun 2016 Tentang Tata Cara Pengajuan Permohonan Pengesahan Badan Hukum Dan Persetujuan Perubahan Anggaran Dasar Perkumpulan jo Permenkumham Nomor 10 Tahun 2019',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(100,11,'Apa yang menjadi dasar hukum terkait pemesanan perkumpulan?','1. Pasal 59 Undang Undang Nomor 17 Tahun 2013\\n2. Permenkumham Nomor 10 Tahun 2019\\n3. Aturan lainnya di luar mengenai perkumpulan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(101,11,'Apa saja persyaratan dokumen yang harus dimiliki untuk pendirian perkumpulan?','Sesuai Pasal 12 Permenkumham Nomor 3 Tahun 2016:\\n1. Salinan akta pendirian Perkumpulan atau salinan akta perubahan pendirian Perkumpulan yang diketahui oleh Notaris sesuai aslinya\\n2. Surat pernyataan tempat kedudukan disertai alamat lengkap Perkumpulan, ditandatangani pengurus dan diketahui lurah/kepala desa setempat\\n3. Sumber pendanaan Perkumpulan\\n4. Program kerja Perkumpulan\\n5. Surat pernyataan tidak sedang dalam sengketa kepengurusan atau perkara di pengadilan\\n6. Notulen rapat pendirian Perkumpulan\\n7. Surat pernyataan kesanggupan dari pendiri untuk memperoleh kartu nomor pokok wajib pajak',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(102,11,'Berapa lama proses verifikasi pemesanan nama perkumpulan?','Proses verifikasi 14 hari kerja, karena banyaknya permohonan yang masuk dan pemeriksaan dilakukan dengan prinsip kehati-hatian, sesuai aturan yang berlaku',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(103,11,'Berapa lama masa aktif akta pendirian perkumpulan?','Tidak ada ketentuan mengenai batas kadaluarsa akta pendirian perkumpulan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(104,11,'Apa saja perubahan yang termasuk perubahan persetujuan perubahan anggaran dasar perkumpulan?','Sesuai Pasal 17 Permenkumham Nomor 3 Tahun 2016, perubahan anggaran dasar meliputi:\\n1. Nama Perkumpulan\\n2. Kegiatan Perkumpulan\\n3. Organ Perkumpulan\\n4. Kedudukan dan/atau alamat Perkumpulan\\n5. Data lainnya yang tercantum dalam anggaran dasar Perkumpulan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(105,11,'Berapa besaran PNBP persetujuan perubahan anggaran dasar?','Berdasarkan Peraturan Pemerintah Nomor 28 Tahun 2019, PNBP untuk permohonan persetujuan anggaran dasar Perkumpulan sebesar Rp 100.000',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(106,11,'Bagaimana tahapan pembubaran perkumpulan?','Permohonan dilakukan secara tertulis yang ditujukan ke Direktorat Jenderal Administrasi Hukum Umum, Kementerian Hukum Dan Hak Asasi Manusia Republik Indonesia, Gedung Direktorat Jenderal Administrasi Hukum Umum, Jalan HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan, DKI Jakarta 12940 Indonesia',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(107,11,'Bagaimana prosedur permohonan salinan SK/SP perkumpulan?','Persyaratan permohonan salinan SK/SP:\\n1. Surat permohonan ditujukan kepada Direktur Perdata, c.q. Subdit Badan Hukum, Jl. HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan 12940, perihal permohonan salinan/duplikat SK/SP\\n2. Surat kehilangan dari Kepolisian, pelaporan oleh ketua pengurus\\n3. Fotokopi akta (legalisir)\\n4. Fotokopi SK/SP yang hilang atau rusak (jika ada)\\n5. Print out voucher PNBP salinan SK atau SP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(108,12,'Apa saja jenis layanan kewarganegaraan melalui sistem administrasi kewarganegaraan elektronik (SAKE)?','1. Permohonan Penyampaian Pernyataan Memilih Kewarganegaraan RI bagi Anak berkewarganegaraan ganda\\n2. Permohonan Surat Keterangan Kehilangan Kewarganegaraan RI (Pasal 23 UU Nomor 12 Tahun 2006)\\n3. Permohonan Kehilangan Kewarganegaraan RI atas Permohonan Sendiri kepada Presiden (Pasal 23 huruf (c) UU Nomor 12 Tahun 2006) jo. Pasal 31 ayat (2) jo. Pasal 35 Peraturan Menteri Hukum dan HAM Nomor 2 Tahun 2007\\n4. Permohonan Ingin Tetap Menjadi Warga Negara Indonesia (Pasal 26 ayat (3) dan ayat (4) UU Nomor 12 Tahun 2006 jo. Pasal 16-20 Peraturan Menteri Hukum dan HAM Nomor 47 Tahun 2016)\\n5. Memperoleh Kembali Kewarganegaraan Republik Indonesia (Pasal 32 UU Nomor 12 Tahun 2006)\\n6. Laporan Kehilangan Kewarganegaraan Republik Indonesia dari Perwakilan RI (Pasal 23 UU Nomor 12 Tahun 2006)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(109,12,'Apa saja jenis layanan kewarganegaraan yang dapat diajukan secara manual?','1. Permohonan Salinan Keputusan Menteri Mengenai Kewarganegaraan RI Bagi Anak Berdasarkan Perkawinan Campuran\\n2. Permohonan Salinan Keputusan Menteri tentang Menyatakan Memilih Kewarganegaraan Bagi Anak Berkewarganegaraan Ganda\\n3. Permohonan Salinan Keputusan Menteri Memperoleh Kembali Kewarganegaraan RI\\n4. Permohonan Salinan Surat Keputusan tentang Tetap Menjadi WNI\\n5. Penegasan Status Kewarganegaraan RI Bagi WNI Keturunan Asing Yang Tidak Memiliki Dokumen\\n6. Penegasan Status Kewarganegaraan RI Bagi WNI Yang Tidak Memiliki Dokumen di Luar Negeri\\n7. Surat Keterangan Status Kewarganegaraan RI (manual)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(110,12,'Apa saja persyaratan untuk Permohonan Penyampaian Pernyataan Memilih Kewarganegaraan RI bagi Anak berkewarganegaraan ganda?','1. Surat permohonan ditandatangani di atas materai 10.000\\n2. Fotokopi akta kelahiran anak yang disahkan\\n3. Fotokopi akta perkawinan/buku nikah orang tua yang disahkan\\n4. Fotokopi akta perkawinan anak (jika berusia <18 tahun tetapi sudah kawin) yang disahkan\\n5. Fotokopi paspor RI dan/atau asing yang disahkan\\n6. Surat pernyataan melepaskan kewarganegaraan asing bermaterai\\n7. Pas foto berwarna 4x6 (2 lembar)\\n8. Fotokopi KTP/KK/NIT yang disahkan\\n9. Keputusan Menteri atau fotokopi affidavit/surat keterangan\\n10. Bukti pembayaran PNBP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(111,12,'Apa saja persyaratan untuk Permohonan Surat Keterangan Kehilangan Kewarganegaraan RI (Pasal 23 UU Nomor 12 Tahun 2006)?','a. Bagi yang belum memperoleh kewarganegaraan asing:\\n1. Surat permohonan bermaterai 10.000\\n2. Fotokopi akta kelahiran yang disahkan\\n3. Fotokopi akta perkawinan (jika ada) yang disahkan\\n4. Fotokopi paspor RI/surat lain yang disahkan\\n5. Surat keterangan naturalisasi asing yang diterjemahkan\\n6. Fotokopi KTP/NIT yang disahkan\\n7. Pas foto 4x6 (2 lembar)\\n8. Bukti pembayaran PNBP\\nb. Bagi yang telah memperoleh kewarganegaraan asing:\\n1. Surat permohonan bermaterai 10.000\\n2. Fotokopi akta kelahiran yang disahkan\\n3. Fotokopi akta perkawinan (jika ada) yang disahkan\\n4. Fotokopi paspor RI/surat lain yang disahkan\\n5. Fotokopi paspor asing/surat lain yang disahkan\\n6. Fotokopi KTP/NIT yang disahkan\\n7. Pas foto 4x6 (2 lembar)\\n8. Bukti pembayaran PNBP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(112,12,'Apa saja persyaratan untuk Permohonan Kehilangan Kewarganegaraan RI atas Permohonan Sendiri kepada Presiden (Pasal 23 huruf (c) UU Nomor 12 Tahun 2006)?','1. Surat permohonan kepada Presiden bermaterai 10.000\\n2. Fotokopi akta kelahiran yang disahkan\\n3. Fotokopi akta perkawinan/perceraian/kematian (jika ada) yang disahkan\\n4. Fotokopi paspor RI/KTP yang disahkan\\n5. Fotokopi KTP/KK/NIT yang disahkan\\n6. Surat keterangan dari perwakilan asing\\n7. Pas foto 4x6 (2 lembar)\\n8. Bukti pembayaran PNBP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(113,12,'Apa saja persyaratan untuk Permohonan Ingin Tetap Menjadi Warga Negara Indonesia (Pasal 26 ayat (3) dan ayat (4) UU Nomor 12 Tahun 2006)?','1. Surat permohonan bermaterai\\n2. Fotokopi akta kelahiran yang disahkan\\n3. Fotokopi paspor RI/surat lain yang disahkan\\n4. Fotokopi akta perkawinan/perceraian/kematian (jika ada) yang disahkan\\n5. Surat pernyataan menolak kewarganegaraan asing bermaterai\\n6. Fotokopi KTP/KK/NIT yang disahkan\\n7. Pas foto 4x6 (2 lembar)\\n8. Bukti pembayaran PNBP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(114,12,'Apa saja persyaratan untuk Permohonan Memperoleh Kembali Kewarganegaraan Republik Indonesia (Pasal 32 UU Nomor 12 Tahun 2006)?','1. Surat permohonan bermaterai\\n2. Fotokopi akta kelahiran yang disahkan\\n3. Fotokopi paspor RI/surat lain yang disahkan\\n4. Fotokopi akta perkawinan/perceraian/kematian (jika ada) yang disahkan\\n5. Fotokopi akta kelahiran anak (jika ada) yang disahkan\\n6. Pernyataan tertulis kesetiaan kepada NKRI\\n7. Fotokopi KTP/KK/NIT yang disahkan\\n8. Daftar riwayat hidup\\n9. Pas foto 4x6 (2 lembar)\\n10. Bukti pembayaran PNBP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(115,12,'Apa saja persyaratan untuk Laporan Kehilangan Kewarganegaraan Republik Indonesia dari Perwakilan RI (Pasal 23 UU Nomor 12 Tahun 2006)?','1. Laporan dari Perwakilan RI/Kantor Imigrasi\\n2. Fotokopi surat perjalanan RI\\n3. Paspor asing/surat tanda kewarganegaraan asing',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(116,12,'Bagaimana prosedur untuk akses layanan kewarganegaraan?','1. Buka laman http://sake.ahu.go.id\\n2. Registrasi dan pilih jenis layanan\\n3. Isi formulir dan unggah dokumen\\n4. Bayar PNBP sesuai PP Nomor 28 Tahun 2019\\n5. Kirim bukti pembayaran dan dokumen fisik ke Ditjen AHU\\n6. Verifikasi dokumen (maksimal 7 hari)\\n7. Unduh dan cetak output layanan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(117,12,'Apa saja output layanan kewarganegaraan?','1. SK Menteri tentang Memilih Kewarganegaraan RI\\n2. Surat Keterangan Kehilangan Kewarganegaraan RI\\n3. Surat Pengantar Kehilangan Kewarganegaraan kepada Presiden\\n4. SK Menteri tentang Tetap Menjadi WNI\\n5. SK Menteri tentang Memperoleh Kembali Kewarganegaraan RI\\n6. SK Menteri tentang Nama Orang yang Kehilangan Kewarganegaraan RI',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(118,12,'Bagaimana proses verifikasi permohonan dan keterangan status warna pada aplikasi SAKE?','1. ANGKA 1 = Verifikasi PBK\\n2. ANGKA 2 = Verifikasi APH\\n3. ANGKA 3 = Verifikasi Kasie\\n4. ANGKA 4 = Verifikasi Kasubdit\\n5. ANGKA 5 = Verifikasi Direktur',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(119,12,'Berapa tarif pembayaran untuk setiap jenis layanan kewarganegaraan?','1. Memperoleh Kewarganegaraan RI (Anak Perkawinan Campuran): Rp. 1.000.000\\n2. Salinan SK Kewarganegaraan RI (Anak Perkawinan Campuran): Rp. 1.000.000\\n3. Memilih Kewarganegaraan RI (Anak Ganda): Rp. 1.000.000\\n4. Salinan SK Memilih Kewarganegaraan (Anak Ganda): Rp. 1.000.000\\n5. Memperoleh Kembali Kewarganegaraan RI: Rp. 1.000.000\\n6. Salinan SK Memperoleh Kembali Kewarganegaraan: Rp. 1.000.000\\n7. Surat Keterangan Kehilangan Kewarganegaraan: Rp. 500.000\\n8. SK Kehilangan Kewarganegaraan kepada Presiden: Rp. 1.000.000\\n9. SK Tetap Menjadi WNI: Rp. 1.000.000\\n10. Salinan SK Tetap Menjadi WNI: Rp. 1.000.000',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(120,12,'Alamat surat menyurat Ditjen AHU','Direktorat Jenderal Administrasi Hukum Umum, Up. Direktur Tata Negara, Cq. Subdit Status Kewarganegaraan, Kementerian Hukum dan HAM RI, Jl. HR. Rasuna Said, Kav 6-7, Kuningan, Jakarta Selatan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(121,12,'Berapa lama SOP proses verifikasi permohonan?','7 hari kerja setelah dokumen diterima oleh Subdit Status Kewarganegaraan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(122,12,'Pemohon tidak mendapat informasi lebih detail di aplikasi SAKE untuk semua pasal terkait pengajuannya jika ada kekurangan berkas atau tidak sesuai.','Hubungi subdit.kewarganegaraan@gmail.com untuk informasi lebih lanjut',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(123,12,'Dokumen apa yang harus diupload di SAKE, bila pemohon belum pernah menikah?','Fotokopi akta/bukti perkawinan orang tua yang disahkan oleh pejabat berwenang/Perwakilan RI (KBRI/KJRI) atau dilegalisir oleh Notaris di Indonesia',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(124,12,'Bagaimana cara follow up untuk permohonan kehilangan yang ditujukan ke Presiden jika permohonan sudah masuk ke Sekretariat Negara?','Hubungi subdit.kewarganegaraan@gmail.com untuk informasi lebih lanjut',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(125,12,'Bagaimana prosedur apabila pemohon tidak memiliki semua dokumen legalitas untuk mengurus permohonan dikarenakan sudah lama tinggal di luar negeri?','Hubungi Kantor Perwakilan RI/KBRI/KJRI setempat untuk pengurusan legalitas dokumen',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(126,12,'Bagaimana cara memperoleh NIT? Di website KBRI sudah tersedia menunya namun masih belum bisa diajukan.','Ajukan melalui laman portal Peduli WNI atau hubungi Perwakilan Dukcapil di Perwakilan RI/KBRI/KJRI setempat',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(127,12,'Bagaimana cara pengajuan permohonan pelepasan kewarganegaraan untuk anak di bawah 21 tahun yang belum memiliki KTP?','Pengajuan melalui laman ahu.go.id. Permohonan kehilangan kewarganegaraan hanya untuk WNI berusia 18 tahun atau sudah kawin dan memiliki KTP',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(128,12,'Bagaimana cara untuk pengajuan permohonan pelepasan kewarganegaraan untuk pemohon yang tidak memiliki KTP/KK?','Hubungi subdit.kewarganegaraan@gmail.com untuk informasi lebih lanjut',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(129,13,'Apa saja syarat untuk menjadi PPNS?','1. Masa kerja sebagai PNS minimal 2 tahun dibuktikan dengan SK pengangkatan PNS\\n2. Berpangkat paling rendah penata muda atau Golongan III/a\\n3. Berpendidikan paling rendah sarjana hukum atau sarjana lain yang setara (S1)\\n4. Bertugas pada bidang teknis operasional penegak hukum\\n5. SK Penugasan/Jabatan terakhir\\n6. Sehat jasmani dan rohani dibuktikan dengan surat keterangan dokter dari rumah sakit pemerintah\\n7. Daftar Penilaian Pelaksanaan Pekerjaan (DP3) PNS selama 2 tahun terakhir dengan minimal penilaian Baik',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(130,13,'Dokumen apa saja yang harus dilampirkan saat pengangkatan PPNS?','1. Fotokopi Surat Tanda Tamat Pendidikan dan Pelatihan (STTPL) dari PUSDIKRESKRIMNAS POLRI\\n2. Surat Rekomendasi dari Kapolri dan Jaksa Agung\\n3. Pasfoto ukuran 4x6 dengan latar belakang merah\\n4. SK Penugasan atau jabatan terakhir',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(131,13,'Dokumen apa saja yang harus dilengkapi saat Sumpah Janji PPNS?','1. Fotokopi SK Pengangkatan\\n2. Lampiran SK Pengangkatan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(132,13,'Apa saja syarat mutasi PPNS?','1. Surat Permohonan Mutasi PPNS\\n2. Fotokopi SK Pengangkatan PPNS\\n3. Fotokopi SK Kenaikan Pangkat Terakhir yang dilegalisasi\\n4. Fotokopi SK Mutasi sesuai penempatan PPNS\\n5. Pasfoto terbaru ukuran 4x6 berlatar belakang merah',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(133,13,'Dokumen apa saja yang harus dilengkapi untuk perpanjangan KTP PPNS?','1. Fotokopi SK Pengangkatan dan Petikan SK PPNS\\n2. Kartu Tanda Penyidik PPNS yang akan berakhir\\n3. Fotokopi Berita Acara Sumpah\\n4. Pasfoto terbaru ukuran 4x6 dengan latar belakang merah',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(134,13,'Apa saja syarat untuk pengangkatan kembali PPNS?','1. Keputusan Pengangkatan/Mutasi Pejabat PPNS\\n2. Keputusan mutasi PNS yang bersangkutan\\n3. Keputusan kenaikan pangkat dan jabatan terakhir\\n4. Petikan Keputusan pemberhentian Pejabat PPNS\\n5. Penugasan Kembali sebagai Pejabat PPNS\\n6. Daftar penilaian perilaku atau pelaksanaan pekerjaan PNS 1 tahun terakhir\\n7. Sasaran kinerja pegawai 1 tahun terakhir\\n8. Kartu tanda pengenal PPNS\\n9. Pas foto terbaru berwarna ukuran 4x6 dengan latar belakang merah',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(135,13,'Dokumen yang harus dilengkapi untuk penerbitan kembali KTP PPNS','1. Kartu Tanda Penyidik PPNS yang rusak atau tidak dapat digunakan\\n2. Surat Lapor Kehilangan dari Kepolisian jika KTP PPNS hilang\\n3. Pasfoto terbaru ukuran 4x6 dengan latar belakang merah',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(136,13,'Persyaratan untuk pemberhentian PPNS','1. Petikan Keputusan Menteri mengenai Pengangkatan atau Mutasi Pejabat PPNS\\n2. Kartu Tanda Pengenal PPNS',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(137,13,'Pemohon Tidak bisa login pada aplikasi PPNS','Koordinator PPNS di Kementerian/LPNK dapat bersurat kepada Direktur Pidana',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(138,13,'Alamat Surat Menyurat','Direktur Pidana, Direktorat Jenderal Administrasi Hukum Umum, Kementerian Hukum dan Hak Asasi Manusia Republik Indonesia, Jalan HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan, DKI Jakarta 12940',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(139,14,'Apa aturan yang berlaku untuk acuan pendaftaran pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018 Tentang Pendaftaran Persekutuan Komanditer, Persekutuan Firma, Dan Persekutuan Perdata Nama CV, Firma, dan Persekutuan Perdata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(140,14,'Bagaimana cara mendaftarkan CV?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018, pendaftaran CV harus melalui Notaris dengan akses menu layanan Sistem Administrasi Badan Usaha (SABU) pada AHU Online. Persyaratan umum:\\n1. Pendiri minimal 2 orang (Peserta Aktif dan Pasif)\\n2. Akta notaris dalam bahasa Indonesia\\n3. Pendiri CV harus warga negara Indonesia',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(141,14,'Bagaimana cara mendaftarkan akta CV lama yang belum di stempel pengadilan?','Pemohon harus membuat akta baru dengan premis menyebutkan akta pendirian yang sudah ada, kemudian mendaftarkan ke Ditjen AHU',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(142,14,'Bagaimana cara mendaftarkan CV lama yang sudah didaftarkan ke pengadilan negeri?','Melakukan pencatatan pendaftaran untuk akta pendirian dan pencatatan perubahan untuk akta perubahan, semua akta harus dicatatkan secara berurutan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(143,14,'Apakah untuk pendaftaran di sistem administrasi badan usaha untuk sekutu bisa dari asing?','Sekutu dalam CV harus warga negara Indonesia',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(144,14,'Bagimana ketentuan pemesanan nama CV pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018, nama CV harus:\\n1. Ditulis dengan huruf latin\\n2. Belum dipakai secara sah oleh CV, Firma, dan Persekutuan Perdata lain dalam Sistem Administrasi Badan Usaha\\n3. Tidak bertentangan dengan ketertiban umum dan/atau kesusilaan\\n4. Tidak sama atau mirip dengan nama lembaga negara, pemerintah, atau internasional kecuali mendapat izin\\n5. Tidak terdiri atas angka, rangkaian angka, huruf, atau rangkaian huruf yang tidak membentuk kata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(145,14,'Apakah saat pengajuan nama CV dapat mengajukan pendaftaran CV tanpa menunggu verifikasi pesan nama CV tersebut?','Setelah pesan nama CV, dapat langsung mengakses pendaftaran CV karena tidak ada proses verifikasi secara manual',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(146,14,'Alamat surat menyurat Ditjen AHU terkait CV','Direktorat Jenderal Administrasi Hukum Umum, UP: Direktorat Perdata, c.q. Subdit Badan Hukum, Kementerian Hukum Dan Hak Asasi Manusia Republik Indonesia, Gedung Direktorat Jenderal Administrasi Hukum Umum, Jalan HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan, DKI Jakarta 12940',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(147,14,'Bagaimana cara mendaftarkan akta CV lama yang belum di stempel pengadilan tapi sudah memiliki NPWP?','Pencatatan CV harus memiliki stempel dari Pengadilan Negeri. Jika tidak, pemohon harus membuat akta baru dengan premis menegaskan kembali akta yang belum dicatatkan dan mendapat cap Pengadilan Negeri, kemudian akses pencatatan CV ke SABU',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(148,14,'Bagaimana cara memperbaiki pencatatan CV yang tidak berurutan atau salah masuk transaksi?','Tidak dapat dilakukan perbaikan pencatatan CV yang tidak berurutan. Pemohon harus membuat akta baru dengan premis menegaskan kembali akta yang belum dicatatkan, kemudian akses pencatatan CV ke SABU',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(149,14,'Bagaimana cara pencatatan pendaftaran CV dengan nama yang menggunakan karakter titik, koma, dan petik?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018, nama CV harus:\\n1. Ditulis dengan huruf latin\\n2. Belum dipakai secara sah oleh CV, Firma, dan Persekutuan Perdata lain dalam Sistem Administrasi Badan Usaha\\n3. Tidak bertentangan dengan ketertiban umum dan/atau kesusilaan\\n4. Tidak sama atau mirip dengan nama lembaga negara, pemerintah, atau internasional kecuali mendapat izin\\n5. Tidak terdiri atas angka, rangkaian angka, huruf, atau rangkaian huruf yang tidak membentuk kata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(150,14,'Peraturan yang berlaku untuk acuan pendaftaran perubahan CV pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018 Tentang Pendaftaran Persekutuan Komanditer, Persekutuan Firma, Dan Persekutuan Perdata Nama CV, Firma, dan Persekutuan Perdata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(151,14,'Pendaftaran perubahan anggaran dasar CV meliputi apa saja?','Pendaftaran perubahan anggaran dasar CV meliputi:\\n1. Identitas pendiri (nama, domisili, dan pekerjaan)\\n2. Kegiatan usaha\\n3. Hak dan kewajiban para pendiri\\n4. Jangka waktu CV',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(152,14,'Bagaimana terkait kendala saat pencatatan perubahan CV muncul nama notaris yang mencatatkan bukan yang membuat akta pendirian karena nama notaris yang melakukan pendirian belum ada di database?','Notaris dapat melakukan perbaikan data terkait nama Notaris dalam CV tersebut',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(153,14,'Bagaimana tahapan untuk pembubaran CV?','Tahapan untuk memperoleh akta pembubaran CV:\\n1. Melakukan pencatatan pendaftaran di sistem administrasi badan usaha untuk mendapatkan Surat Keterangan Terdaftar\\n2. Melakukan pembubaran CV pada sistem administrasi badan usaha untuk mendapatkan SK pembubaran',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(154,14,'Apakah perlu menggunakan pengumuman koran saat pembubaran CV?','Belum ada aturan khusus mengenai pengumuman koran, sehingga saat ini tidak diperlukan. Namun, untuk tertib administrasi, disarankan melakukan pengumuman koran agar para pihak mengetahuinya',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(155,14,'Bagaimana ketentuan pemesanan nama Firma pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018, nama Firma harus:\\n1. Ditulis dengan huruf latin\\n2. Belum dipakai secara sah oleh CV, Firma, dan Persekutuan Perdata lain dalam Sistem Administrasi Badan Usaha\\n3. Tidak bertentangan dengan ketertiban umum dan/atau kesusilaan\\n4. Tidak sama atau mirip dengan nama lembaga negara, pemerintah, atau internasional kecuali mendapat izin\\n5. Tidak terdiri atas angka, rangkaian angka, huruf, atau rangkaian huruf yang tidak membentuk kata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(156,14,'Apa solusi untuk kendala terkait tidak dapat mendaftarkan nama firma karena ada pembatasan kata?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018, nama Firma harus:\\n1. Ditulis dengan huruf latin\\n2. Belum dipakai secara sah oleh CV, Firma, dan Persekutuan Perdata lain dalam Sistem Administrasi Badan Usaha\\n3. Tidak bertentangan dengan ketertiban umum dan/atau kesusilaan\\n4. Tidak sama atau mirip dengan nama lembaga negara, pemerintah, atau internasional kecuali mendapat izin\\n5. Tidak terdiri atas angka, rangkaian angka, huruf, atau rangkaian huruf yang tidak membentuk kata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(157,14,'Apa perbedaan Persekutuan Perdata dengan Firma, berikut contohnya?','Persekutuan Perdata: Perjanjian antara dua orang atau lebih untuk memasukkan sesuatu ke dalam persekutuan dengan tujuan membagi keuntungan (Pasal 1618 KUHPerdata). Contoh: Persekutuan para pengacara, dokter, arsitek, akuntan, yang tidak menggunakan nama bersama.\\nFirma: Badan usaha yang didirikan dengan nama bersama sekutu. Contoh: Firma hukum, firma akuntansi',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(158,14,'Peraturan yang berlaku untuk acuan pendaftaran perubahan Firma pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018 Tentang Pendaftaran Persekutuan Komanditer, Persekutuan Firma, Dan Persekutuan Perdata Nama CV, Firma, dan Persekutuan Perdata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(159,14,'Pendaftaran perubahan anggaran dasar Firma meliputi apa saja?','Pendaftaran perubahan anggaran dasar Firma meliputi:\\n1. Identitas pendiri (nama, domisili, dan pekerjaan)\\n2. Kegiatan usaha\\n3. Hak dan kewajiban para pendiri\\n4. Jangka waktu Firma',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(160,14,'Saat pencatatan perubahan Firma muncul nama notaris yang mencatatkan bukan yang membuat akta pendirian karena nama notaris yang melakukan pendirian belum ada di database?','Pemohon bisa melakukan perbaikan data terkait nama Notaris dalam Firma tersebut',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(161,14,'Peraturan yang berlaku untuk acuan pembubaran Firma pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018 Tentang Pendaftaran Persekutuan Komanditer, Persekutuan Firma, Dan Persekutuan Perdata Nama CV, Firma, dan Persekutuan Perdata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(162,14,'Apakah perlu menggunakan pengumuman koran saat pembubaran Firma?','Belum ada aturan khusus mengenai pengumuman koran, sehingga saat ini tidak diperlukan. Namun, untuk tertib administrasi, disarankan melakukan pengumuman koran agar para pihak mengetahuinya',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(163,14,'Bagaimana ketentuan pemesanan nama Persekutuan Perdata pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018, nama Persekutuan Perdata harus:\\n1. Ditulis dengan huruf latin\\n2. Belum dipakai secara sah oleh CV, Firma, dan Persekutuan Perdata lain dalam Sistem Administrasi Badan Usaha\\n3. Tidak bertentangan dengan ketertiban umum dan/atau kesusilaan\\n4. Tidak sama atau mirip dengan nama lembaga negara, pemerintah, atau internasional kecuali mendapat izin\\n5. Tidak terdiri atas angka, rangkaian angka, huruf, atau rangkaian huruf yang tidak membentuk kata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(164,14,'Peraturan yang berlaku untuk acuan pendaftaran perubahan Persekutuan Perdata pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018 Tentang Pendaftaran Persekutuan Komanditer, Persekutuan Firma, Dan Persekutuan Perdata Nama CV, Firma, dan Persekutuan Perdata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(165,14,'Pendaftaran perubahan anggaran dasar Persekutuan Perdata meliputi apa saja?','Pendaftaran perubahan anggaran dasar Persekutuan Perdata meliputi:\\n1. Identitas pendiri (nama, domisili, dan pekerjaan)\\n2. Kegiatan usaha\\n3. Hak dan kewajiban para pendiri\\n4. Jangka waktu Persekutuan Perdata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(166,14,'Saat pencatatan perubahan Persekutuan Perdata muncul nama notaris yang mencatatkan bukan yang membuat akta pendirian karena nama notaris yang melakukan pendirian belum ada di database?','Pemohon bisa melakukan perbaikan data terkait nama Notaris dalam Persekutuan Perdata tersebut',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(167,14,'Peraturan yang berlaku untuk acuan pembubaran Persekutuan Perdata pada sistem administrasi badan usaha?','Berdasarkan Peraturan Menteri Hukum Dan Hak Asasi Manusia Republik Indonesia Nomor 17 Tahun 2018 Tentang Pendaftaran Persekutuan Komanditer, Persekutuan Firma, Dan Persekutuan Perdata Nama CV, Firma, dan Persekutuan Perdata',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(168,14,'Apakah perlu menggunakan pengumuman koran saat pembubaran Persekutuan Perdata?','Belum ada aturan khusus mengenai pengumuman koran, sehingga saat ini tidak diperlukan. Namun, untuk tertib administrasi, disarankan melakukan pengumuman koran agar para pihak mengetahuinya',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(169,15,'Bagaimana tahapan untuk mendirikan partai politik?','Mengirimkan surat permohonan kepada Menteri Hukum dan HAM, kemudian mengirimkan dokumen persyaratan sebagaimana diatur dalam Permenkumham Nomor 34 Tahun 2017 tentang Tata Cara Pendaftaran Pendirian Badan Hukum, Perubahan AD/ART dan Perubahan Kepengurusan Partai Politik',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(170,15,'Apa saja dokumen persyaratan untuk mendirikan partai politik?','1. Surat permohonan pendaftaran pendirian dan pembentukan partai politik baru ditujukan kepada Menteri Hukum dan Hak Asasi Manusia\\n2. Satu salinan sah Akta Notaris tentang pendirian dan pembentukan partai politik baru yang memuat nama pendiri\\n3. Anggaran Dasar/Rumah Tangga dan kepengurusan partai tingkat pusat\\n4. Surat Keputusan (SK) tentang kepengurusan tingkat pusat, provinsi\\n5. Surat Keputusan (SK) tentang kepengurusan di 75 % Kabupaten/Kota pada Provinsi yang bersangkutan\\n6. Surat Keputusan (SK) tentang kepengurusan di 50 % Kecamatan pada Kabupaten/Kota yang bersangkutan\\n7. Surat Keterangan terdaftar dari Pemerintah Daerah Tingkat Provinsi di seluruh Provinsi\\n8. Surat Keterangan terdaftar dari Pemerintah Daerah Tingkat Kabupaten/Kota di seluruh 75 % Kabupaten/Kota pada Provinsi yang bersangkutan\\n9. Surat Keterangan terdaftar dari Kepala Kantor Wilayah Kementerian Hukum dan HAM di Seluruh Provinsi\\n10. Surat Keterangan Domisili Partai Politik Tingkat Pusat dari kelurahan/desa atau nama lain yang sejenis\\n11. Surat Keterangan Domisili Partai Politik Tingkat Provinsi dari kelurahan/desa atau nama lain yang sejenis di seluruh Provinsi\\n12. Surat Keterangan Domisili Partai Politik Tingkat Kabupaten/Kota dari kelurahan/desa atau nama lain yang sejenis di 75 % Kabupaten/Kota pada Provinsi yang bersangkutan\\n13. Surat Keterangan Domisili Partai Politik Tingkat Kecamatan dari kelurahan/desa atau nama lain yang sejenis di 50 % Kecamatan pada Kabupaten/Kota yang bersangkutan\\n14. Nama, lambang, atau tanda gambar partai politik\\n15. Surat Pernyataan sebagai pengurus partai politik disertai dengan fotokopi kartu tanda penduduk\\n16. Fotokopi rekening atas nama Partai Politik\\n17. Bukti Pembayaran Penerimaan Negara Bukan Pajak (PNBP)\\n18. Bukti Kantor tetap pada tingkat pusat, provinsi, dan kabupaten/kota sampai tahapan terakhir pemilihan umum',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(171,15,'Berapa lama proses untuk mendirikan partai politik?','Berdasarkan Permenkumham Nomor 34 Tahun 2017, sekitar 67 hari sejak dokumen persyaratan dinyatakan lengkap: 45 hari tahapan verifikasi, 15 hari penyiapan SK, dan 7 hari penyampaian SK ke pemohon',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(172,15,'Berapa biaya untuk mendaftar partai politik?','Sesuai dengan PP Nomor 28 Tahun 2019, sebesar 100 juta rupiah',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(173,15,'Bagaimana prosedur pembayaran PNBP pendirian partai politik?','Melalui Simpadhu di website www.ahu.go.id',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(174,15,'Kapan harus membayar PNBP?','Di awal saat akan melakukan pendaftaran (menjadi dokumen persyaratan)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(175,15,'Apabila permohonan ditolak, apakah bisa dikembalikan PNBP nya?','Sesuai dengan PP Nomor 28 Tahun 2019, PNBP dibayarkan per permohonan, sehingga ketika permohonan ditolak PNBP tidak dapat dikembalikan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(176,15,'Apakah ada persyaratan untuk pemilihan nama partai politik?','Berdasarkan Pasal 40 UU Nomor 2 Tahun 2008, Partai Politik dilarang menggunakan nama, lambang, atau tanda gambar yang sama dengan:\\n1. Bendera atau lambang negara Republik Indonesia\\n2. Lambang lembaga negara atau lambang Pemerintah\\n3. Nama, bendera, lambang negara lain atau lembaga/badan internasional\\n4. Nama, bendera, simbol organisasi gerakan separatis atau organisasi terlarang\\n5. Nama atau gambar seseorang\\n6. Yang mempunyai persamaan pada pokoknya atau keseluruhannya dengan nama, lambang, atau tanda gambar Partai Politik lain',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(177,15,'Bagaimana prosedur pengajuan terkait dengan syarat Surat Keterangan Terdaftar di Kanwil?','Berdasarkan Surat Edaran Dirjen AHU Nomor AHU.UM.01.01-6 Tahun 2020, pengurus partai wajib mengajukan permohonan Surat Keterangan Terdaftar yang ditandatangani oleh Ketua Umum dan Sekjen kepada Kakanwil, dilampirkan dengan fotokopi SK tentang kepengurusan tingkat provinsi dan mengisi format SKT',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(178,15,'Apakah saat mendirikan partai politik harus menyertakan mahkamah partai?','Berdasarkan Pasal 32 ayat (3) UU Nomor 2 Tahun 2011 tentang Perubahan atas UU Nomor 2 Tahun 2008, susunan mahkamah Partai Politik atau sebutan lain wajib disampaikan oleh Pimpinan Partai Politik kepada Kementerian saat mendaftar',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(179,15,'Apa persyaratan apabila ingin melakukan perubahan AD/ART?','1. Surat permohonan yang ditandatangani oleh Ketua Umum dan Sekretaris Jenderal\\n2. Salinan sah Akta notaris tentang perubahan AD/ART partai politik\\n3. Daftar hadir peserta munas/kongres/muktamar yang diketahui oleh Ketua Umum dan Sekjen\\n4. Notula munas/kongres/muktamar yang diketahui oleh Ketua Umum dan Sekjen\\n5. Dokumentasi munas/kongres/muktamar yang diketahui oleh Ketua Umum dan Sekjen\\n6. Surat keterangan tidak dalam perselisihan internal partai politik dari mahkamah partai politik atau sebutan lain\\n7. Bukti pembayaran Penerimaan Negara Bukan Pajak (PNBP)\\n8. Fotokopi nama, lambang, dan tanda gambar partai politik, jika melakukan perubahan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(180,15,'Berapa biaya untuk melakukan perubahan AD/ART partai politik?','Sesuai dengan PP Nomor 28 Tahun 2019, PNBP sebesar 5 juta per permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(181,15,'Apa persyaratan jika ingin melakukan perubahan kepengurusan?','1. Surat permohonan yang ditandatangani oleh Ketua Umum dan Sekretaris Jenderal\\n2. Salinan sah Akta notaris tentang pergantian kepengurusan partai politik\\n3. Daftar hadir peserta munas/kongres/muktamar yang diketahui oleh Ketua Umum dan Sekjen\\n4. Notula munas/kongres/muktamar yang diketahui oleh Ketua Umum dan Sekjen\\n5. Dokumentasi munas/kongres/muktamar yang diketahui oleh Ketua Umum dan Sekjen\\n6. Surat keterangan tidak dalam perselisihan internal partai politik dari mahkamah partai politik atau sebutan lain\\n7. Bukti pembayaran Penerimaan Negara Bukan Pajak (PNBP)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(182,15,'Berapa biaya untuk melakukan perubahan kepengurusan partai politik?','Sesuai dengan PP Nomor 28 Tahun 2019, PNBP sebesar 5 juta per permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(183,15,'Alamat surat menyurat Ditjen AHU berkaitan dengan partai politik','Direktorat Jenderal Administrasi Hukum Umum, UP: Direktorat Tata Negara, c.q. Subdit Partai Politik, Kementerian Hukum dan Hak Asasi Manusia Republik Indonesia, Gedung Direktorat Jenderal Administrasi Hukum Umum, Jalan HR. Rasuna Said Kav. 6-7, Kuningan, Jakarta Selatan, DKI Jakarta 12940 Indonesia',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(184,15,'Konsultasi partai politik','Konsultasi dapat dilakukan melalui email partaipolitikahu@gmail.com',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(185,17,'Bagaimana mekanisme pendaftaran Jaminan Fidusia dan apa saja yang harus dipenuhi?','Pendaftaran Jaminan Fidusia dilakukan secara online. Pemohon (penerima fidusia, kuasa, atau wakilnya) harus memiliki user ID dan password pada aplikasi fidusia online. Langkah-langkah pendaftaran dapat dilihat di: https://panduan.ahu.go.id/doku.php?id=pendaftaran_fidusia. Pemohon harus memenuhi ketentuan Pasal 11–14 UU No. 42 Tahun 1999 tentang Jaminan Fidusia dan Pasal 3–7 PP No. 21 Tahun 2015 tentang Tata Cara Pendaftaran Jaminan Fidusia dan Biaya Pembuatan Akta Jaminan Fidusia.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(186,17,'Apa saja jenis layanan fidusia?','Jenis layanan di aplikasi fidusia:\\n1. Pendaftaran Jaminan Fidusia\\n2. Perbaikan Sertifikat Jaminan Fidusia\\n3. Perubahan Sertifikat Jaminan Fidusia\\n4. Pencarian/unduh data jaminan fidusia\\n5. Penghapusan Jaminan Fidusia',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(187,17,'Apakah surat kontrak kerja dapat dijadikan jaminan dalam fidusia?','Hak tagih atau piutang atas nama yang tercantum dalam Surat Perintah Kerja dapat dijadikan Jaminan Fidusia, sebagaimana diatur dalam Pasal 9 UU No. 42 Tahun 1999 tentang Jaminan Fidusia, jika menunjukkan hubungan antara pengguna dan penyedia jasa yang menimbulkan hak tagih atas pembayaran setelah proyek selesai.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(188,17,'Apakah bangunan (tanpa tanahnya) dapat dijaminkan secara Fidusia dan apa saja kelengkapan yang harus dipenuhi oleh pemilik bangunan dan penerima jaminan (kreditur)?','Jaminan Fidusia mencakup benda bergerak dan tidak bergerak, baik berwujud maupun tidak berwujud, yang tidak dapat dibebani hak tanggungan atau hipotek. Jika bangunan dapat dibebani hak tanggungan/hipotek, maka tidak dapat difidusiakan. Jika tidak, maka dapat dijadikan Jaminan Fidusia sesuai ketentuan perundang-undangan tentang hak tanggungan/hipotek.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(189,17,'Bagaimana mekanisme perubahan sertifikat Jaminan Fidusia?','Perubahan sertifikat Jaminan Fidusia dilakukan secara online. Pemohon (penerima fidusia, kuasa, atau wakilnya) harus memiliki user ID dan password pada aplikasi fidusia online. Langkah-langkah perubahan dapat dilihat di: https://panduan.ahu.go.id/doku.php?id=perubahan_fidusia. Pemohon harus memenuhi ketentuan Pasal 16 UU No. 42 Tahun 1999 dan Pasal 11–15 PP No. 21 Tahun 2015.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(190,17,'Apakah addendum fidusia bisa dipisah dua akta dengan masing-masing nilai objek fidusia?','Pendaftaran atau perubahan sertifikat Jaminan Fidusia cukup dituangkan dalam satu akta, karena aplikasi fidusia online hanya menerima satu akta.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(191,17,'Bagaimana mekanisme dan syarat melakukan penghapusan Jaminan Fidusia?','Penghapusan Jaminan Fidusia dilakukan secara online. Pemohon (penerima fidusia, kuasa, atau wakilnya) harus memiliki user ID dan password pada aplikasi fidusia online. Langkah-langkah penghapusan dapat dilihat di: https://panduan.ahu.go.id/doku.php?id=penghapusan. Pemohon harus memenuhi ketentuan Pasal 25 UU No. 42 Tahun 1999 dan Pasal 16–17 PP No. 21 Tahun 2015.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(192,17,'Apa saja jenis penghapusan Jaminan Fidusia?','Jenis penghapusan Jaminan Fidusia:\\n1. Penghapusan karena pelunasan\\n2. Penghapusan karena pelepasan hak\\n3. Musnahnya benda yang menjadi objek Jaminan Fidusia',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(193,17,'Bagaimana mekanisme penghapusan Jaminan Fidusia untuk data baru?','Mekanisme penghapusan Jaminan Fidusia untuk data baru:\\n1. Pilih jenis penghapusan Jaminan Fidusia\\n2. Masukkan Nomor Sertifikat Pendaftaran\\n3. Masukkan Tanggal Sertifikat Fidusia\\n4. Masukkan Nama Notaris yang melakukan pendaftaran\\n5. Masukkan Kedudukan Notaris\\n6. Klik untuk memproses data yang akan diubah',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(194,17,'Bagaimana mekanisme penghapusan/roya fidusia untuk data lama?','Mekanisme penghapusan Jaminan Fidusia untuk data lama:\\n1. Pilih jenis penghapusan Jaminan Fidusia\\n2. Masukkan Nomor Sertifikat Pendaftaran\\n3. Masukkan Tanggal Sertifikat Fidusia\\n4. Masukkan Waktu Sertifikat Pendaftaran (jam, menit, detik)\\n5. Masukkan Nama Notaris yang melakukan pendaftaran\\n6. Masukkan Kedudukan Notaris\\n7. Klik untuk memproses data yang akan diubah',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(195,17,'Bagaimana solusi tidak ada pilihan penghapusan berdasarkan tukar jaminan hak, yang ada hanya penghapusan karena pelunasan atau pelepasan hak saat ingin melakukan pemberitahuan penghapusan Jaminan Fidu','Jika terjadi perubahan objek jaminan atau peralihan kredit ke kreditur/pemberi fidusia lain, lakukan perubahan sertifikat Jaminan Fidusia. Jika objek jaminan tidak lagi dijaminkan dengan fidusia, ajukan penghapusan karena pelepasan hak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(196,17,'Bagaimana mekanisme dan syarat melakukan perbaikan sertifikat Jaminan Fidusia?','Perbaikan sertifikat Jaminan Fidusia dilakukan secara online. Pemohon (penerima fidusia, kuasa, atau wakilnya) harus memiliki user ID dan password pada aplikasi fidusia online. Langkah-langkah perbaikan dapat dilihat di: https://panduan.ahu.go.id/doku.php?id=perbaikan_fidusia. Pemohon harus memenuhi ketentuan Pasal 9–10 PP No. 21 Tahun 2015.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(197,17,'Bagaimana cara untuk perbaikan sertifikat Jaminan Fidusia yang diajukan prosesnya dapat dipercepat?','Perbaikan sertifikat Jaminan Fidusia berdasarkan SOP memakan waktu 3 hari kerja. Jika melebihi waktu tersebut, pemohon dapat memberikan data lengkap SJF yang akan diperbaiki untuk ditindaklanjuti oleh PIC setelah pengecekan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(198,17,'Bagaimana mekanisme dan syarat melakukan permohonan Pencarian/Unduh data Jaminan Fidusia?','Klik panduan pada AHU online, pilih \'Pencarian/Unduh data\'. Format pencarian sesuai Pasal 4 ayat (1) dan (2) Permenkumham No. 17 Tahun 2020, berdasarkan:\\n1. Nomor sertifikat jaminan fidusia\\n2. Objek berserial nomor\\n3. Objek tidak berserial nomor\\n4. Pemberi fidusia\\n5. Penerima fidusia\\nJika terdaftar, klik beli data, isi data perorangan/korporasi, bayar PNBP, dan data akan dikirim otomatis ke email terdaftar sesuai Pasal 5–7 Permenkumham No. 17 Tahun 2020.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(199,18,'Bagaimana cara mengetahui proses permohonan pewarganegaraan bagi pemohon?','1. Pemohon datang ke Kanwil Kemenkumham sesuai domisili dengan dokumen persyaratan\\n2. Kanwil memeriksa administrasi dokumen; jika lengkap, Tim Terpadu (TP4) melakukan pemeriksaan substantif, jika tidak, dokumen dikembalikan\\n3. TP4 melakukan wawancara dan mengeluarkan Berita Acara Pemeriksaan (BAP)\\n4. Kanwil mengirim dokumen dan BAP ke Ditjen AHU secara elektronik dan non-elektronik\\n5. Ditjen AHU memeriksa secara substantif di Subdit Pewarganegaraan\\n6. Jika dokumen tidak lengkap, Kanwil diberitahu untuk melengkapi\\n7. Jika lengkap, dibuatkan surat pengantar ke Badan Intelijen Negara (BIN)\\n8. BIN memeriksa dokumen secara substantif\\n9. BIN mengeluarkan pertimbangan pemberian kewarganegaraan RI\\n10. Kemenkumham membuat surat pengantar ke Presiden melalui Setneg\\n11. Setneg memeriksa dokumen; jika ada ketidaksesuaian, meminta klarifikasi; jika lengkap, menerbitkan Keppres Pewarganegaraan\\n12. Setneg mengirim petikan Keppres ke Kanwil dan salinan ke Menkumham\\n13. Kanwil memanggil pemohon untuk sumpah/janji setia dalam 3 bulan\\n14. Kanwil mengirim Berita Acara Sumpah (BAS) ke Menkumham\\n15. Pemohon mengembalikan dokumen keimigrasian/kependudukan ke kantor imigrasi dalam 14 hari setelah sumpah\\n16. Pemohon mengembalikan dokumen asing ke perwakilan negara',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(200,18,'Berapa lama SOP proses verifikasi permohonan?','165 hari kerja\\nUU No.12 Tahun 2006 dan PP No.2 Tahun 2007 tidak mengatur jangka waktu pasti\\nDalam praktik, proses memakan waktu 1 hingga 4 tahun',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(201,19,'Apakah saya dapat menggunakan akun Alegtron?','Ya, anda dapat menggunakan akun Aplikasi Legalisasi Elektronik (Alegtron) yang sudah anda punya untuk login Aplikasi Legalisasi Apostille.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(202,19,'Bagaimana apabila saya lupa password akun?','Silakan lakukan reset password melalui tautan https://apostille.ahu.go.id/reset-password.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(203,19,'Bagaimana apabila saya belum mendapatkan e-mail aktivasi akun?','Silakan lakukan aktivasi ulang melalui tautan https://apostille.ahu.go.id/aktivasi-akun/ulang.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(204,19,'Siapa yang dapat mengajukan permohonan Apostille?','Pihak yang dapat mengajukan permohonan Apostille adalah pihak yang namanya tercantum pada dokumen yang diajukan atau penerima kuasanya (dibuktikan dengan surat kuasa bermaterai). Untuk dokumen suatu badan, maka yang dapat mengajukan adalah pemilik/pejabat/pegawai pada badan tersebut (dibuktikan dengan surat keterangan resmi) atau penerima kuasanya (dibuktikan dengan surat kuasa bermaterai).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(205,19,'Bagaimana apabila saya ingin mengajukan permohonan Apostille untuk dokumen milik keluarga saya?','Anda harus mencantumkan dokumen resmi yang membuktikan hubungan kekeluargaan seperti Kartu Keluarga. Untuk dokumen tertentu yang mencantumkan hubungan kekeluargaan langsung seperti Akta Kelahiran (mencantumkan nama orang tua), tidak perlu dicantumkan dokumen resmi yang membuktikan hubungan kekeluargaan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(206,19,'Apakah Sertifikat Apostille dari negara asing perlu dilegalisasi lebih lanjut?','Tidak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(207,19,'Apakah saya perlu melakukan legalisasi ke Kementerian Luar Negeri dan Kedutaan Negara Asing di Indonesia setelah Sertifikat Apostille terbit?','Tidak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(208,19,'Apakah Sertifikat Apostille memiliki jangka waktu (kedaluwarsa)?','Tidak. Namun demikian, dokumen yang dilekatkan Sertifikat Apostille mungkin memiliki tanggal kadaluwarsa (contoh: Surat Keterangan Catatan Kepolisian).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(209,19,'Apakah Sertifikat Apostille yang diterbitkan negara asing sebelum tanggal 4 Juni 2022 dapat digunakan di Indonesia?','Ya, Sertifikat Apostille yang diterbitkan negara asing sebelum tanggal 4 Juni 2022 dapat digunakan di Indonesia.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(210,19,'bagaimana prosedure apostille','*PROSEDUR PENGAJUAN SECARA MANDIRI/ONLINE*\\r\\n Untuk Permohonan/Pendaftaran Apostille dapat diajukan secara mandiri melalui website https://layanan.ahu.go.id/ahu\\r\\n Prosedur mengajukan permohonan Apostille: \\r\\n\\r\\n 1. Masuk ke Website AHU pilih menu AHU Legalisasi-Apostille \\r\\n2. Membuat akun apostille\\r\\n3. Memilih jenis dokumen yang akan di Apostille\\r\\n4. Memilih negara tujuan penggunaan dokumen\\r\\n5. Memasukkan data pemohon dan data dokumen\\r\\n6. Upload dokumen yang akan di Apostille kan\\r\\n7. Submit permohonan Apostille\\r\\n\\r\\nUntuk Prosedur Permohonan Apostille selengkapnya, dapat dibaca di : https://layanan.ahu.go.id/ahu/layanan-produk/hukum-international/apostille\\r\\n\\r\\n*PROSEDUR PENGAJUAN MELALUI KANWIL*\\r\\nApabila mengalami kesulitan, Kanwil DIY membuka pelayanan secara offline di Kantor Kami pada hari Senin - Kamis Pukul 08.00 - 15.00 WIB\\r\\n\\r\\n*WAKTU*\\r\\nSetiap pengajuan Apostille, akan diverifikasi selama 3 Hari Kerja.\\r\\n\\r\\n*BIAYA*\\r\\nSetelah berhasil diverifikasi, Pemohon dapat melakukan Pembayaran.\\r\\n\\r\\nBiaya Apostille sebesar Rp. 150.000,- /  Dokumen (Bukan Per Lembar) \\r\\n*yang akan masuk sebagai PNBP (Penerimaan Negara Bukan Pajak).\\r\\n\\r\\n*PENCETAKAN*\\r\\nSetelah Permohonan Apostille di Setujui dan telah dibayar, maka proses selanjutnya adalah Pencetakan Sertifikat Apostille di Kantor Wilayah / Tempat yang telah dipilih pada saat Pengajuan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(211,19,'kapan cetak apostille','Pelayanan pencetakan dilayani pada Hari Senin - Kamis Pukul 08.00 - 15.00 WIB.\\r\\nProses pencetakan kurang lebih 15 menit.\\r\\n\\r\\nUntuk pencetakan membawa :\\r\\n1. Dokumen Identitas (KTP)\\r\\n2. Dokumen Asli\\r\\n3. Surat Kuasa, apabila diambilkan oleh orang lain',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(212,19,'Apa dasar hukum pelaksanaan Layanan Apostille?','1. Convention Abolishing the Requirement of Legalisation for Foreign Public Documents.\\n2. Peraturan Presiden Republik Indonesia Nomor 2 Tahun 2021 tentang Pengesahan Convention Abolishing the Requirement of Legalisation for Foreign Public Documents (Konvensi Penghapusan Persyaratan Legalisasi terhadap Dokumen Publik Asing).\\n3. Peraturan Menteri Hukum dan Hak Asasi Manusia Republik Indonesia Nomor 6 Tahun 2022 tentang Layanan Legalisasi Apostille pada Dokumen Publik.\\n4. Peraturan Menteri Keuangan Republik Indonesia Nomor 101/PMK.02/2022 tentang Jenis dan Tarif Penerimaan Negara Bukan Pajak Kebutuhan Mendesak atas Layanan Legalisasi Apostille pada Dokumen Publik yang Berlaku pada Kementerian Hukum dan Hak Asasi Manusia.\\n5. Keputusan Menteri Hukum dan Hak Asasi Manusia Republik Indonesia Nomor M.HH-01.AH.03.01 Tahun 2022 tentang Daftar Jenis Dokumen Layanan Legalisasi Apostille pada Dokumen Publik.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(213,19,'jangka waktu verifikasi apostille','Paling lama 3 hari kerja setelah permohonan diterima',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(214,19,'tarif/biaya apostille','Rp150.000,00 per dokumen',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(215,19,'voucher apostille','Voucher PNBP dapat diunduh pada Daftar Permohonan akun Anda. Selain itu juga dapat diunduh pada Email pemohon.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(216,19,'syarat cetak apostille','Saat mencetak Sertifikat Apostille pemohon membawa kelengkapan berikut:\\n\\na. Dokumen yang diajukan \\nb. Bukti pembayaran\\nc. Kartu Identitas\\nd. Surat Kuasa bermeterai Rp10.000,00 (apabila mewakili pihak lain)\\nDokumen yang sudah dilekatkan Sertifikat Apostille tidak perlu dilegalisasi ke Kementerian Luar Negeri dan Kedutaan Negara Asing di Indonesia.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(217,19,'pengajuan dokumen milik keluarga untuk apostille','Anda harus mencantumkan dokumen resmi yang membuktikan hubungan kekeluargaan seperti Kartu Keluarga. \\n\\nUntuk dokumen tertentu yang mencantumkan hubungan kekeluargaan langsung seperti Akta Kelahiran (mencantumkan nama orang tua), tidak perlu dicantumkan dokumen resmi yang membuktikan hubungan kekeluargaan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(218,31,'informasi magang','Kanwil Kemenkum DIY, membuka Layanan Magang Bagi Mahasiswa/i.\\r\\n\\r\\n- PROSEDUR PENGAJUAN MAGANG\\r\\nProsedur pengajuan Penelitian/Observasi di Kanwil Kemenkum DIY, sebagai berikut :\\r\\n1. Pemohon mengajukan Melalui Google Form https://s.id/magangkanwildiy\\r\\n2. Pemohon melampirkan dokumen pendukung pada Google Form tersebut\\r\\n3. Proses Verifikasi Dokumen Permohonan Magang Selama 7 Hari Kerja\\r\\n3. Apabila telah disetujui, Kanwil Kemenkum DIY akan mengeluarkan Surat Izin Magang kepada Ybs;\\r\\n\\r\\n- SYARAT DOKUMEN\\r\\nUntuk Pengajuan Magang, Kanwil Kemenkum DIY membutuhkan dokumen sebagai berikut :\\r\\n1. Surat Permohonan Magang yang dikeluarkan oleh Kampus\\r\\n2. Proposal Magang\\r\\n\\r\\n- KUOTA MAGANG\\r\\nSaat ini, Kanwil Kemenkum DIY membatasi Jumlah Kuota sebanyak 10 Mahasiswa/Bulan\\r\\n\\r\\n- CATATAN\\r\\nSehubungan dengan keterbatasan Kuota, silahkan bisa menghubungi Helpdesk untuk sisa Kuota sebelum pengajuan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(219,31,'pertanyaan seputar keimigrasian dan lapas pemasyarakatan','Sehubungan dengan adanya restrukturisasi Kementerian. Saat ini Lapas sudah tidak menjadi Binaan Kanwil Kementerian Hukum. akan tetapi saat ini berada di Binaan Kanwil Ditjen Pemasyarakatan, \\n Untuk itu, Jika Kakak ingin menghubungi Kanwil DitjenPAS DIY dapat menghubungi contact center di 085169767212. \\n Demikian yg bisa kami informasikan kak, Semoga membantu.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(220,31,'alamat kanwil kementerian hukum daerah istemewa yogyakarta','Kantor Wilayah Kementerian Hukum Daerah Istimewa Yogyakarta \\r\\nJl. Gedongkuning No. 146 Rejowinangun, Kotagede, Yogyakarta, Daerah Istimewa Yogyakarta 55171 \\r\\nTelpon: (0274) 378431 / Faksimili: (0274) 378432, 373195 / Whatsapp : 08112640146\\r\\nGoogle Maps : https://maps.app.goo.gl/1CngRpBy2HJY9B5r7',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(221,19,'pembayaran apostille','Untuk pembayaran Apostille, bisa dilakukan pembayaran melalui berbagai macam channel pembayaran.\\r\\nSilahkan ikuti tutorial berikut ini yaa kak : https://jogja.kemenkum.go.id/faq/tutorial-cara-bayar-pnbp-ahu',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(222,19,'status pembayaran apostille','Mengenai status pembayaran apostil yang belum terbayar, Kakak dapat melakukan konfirmasi pembayaran melalui link berikut ini:\\r\\n\\r\\nhttps://ahu.go.id/billing/paymentConfirm\\r\\n\\r\\nSetelah pengisian form di atas, verifikasi data membutuhkan waktu kurang lebih 10-15 menit. Silakan cek status pembayarannya secara berkala.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(223,31,'pelayanan offline','Apabila mengalami kesulitan, Kanwil DIY membuka asistensi secara offline di Kantor Kami pada hari Senin - Kamis Pukul 08.00 - 15.00 WIB',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(224,31,'permohonan mutasi ke kemenkum','Baik, terkait dengan mutasi antar kementerian/lembaga merupakan kewenangan dari Birowai setjen nggih Bu.\\r\\nBiasanya informasi pembukaan disampaikan melalui pengumuman di website https://kemenkum.go.id/ ataupun di sosial media setjen kemenkum. \\r\\n\\r\\nSilahkan bisa mengikuti informasi dari kanal tersebut. ðŸ™ðŸ™',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(225,31,'lisensi musik agar bisa diputar di cafe','Terkait dengan penggunaan lisensi musik, saat ini dikelola oleh LMKN (Lembaga Manajemen Kolektif). Informasi lebih detailnya bisa dikunjungi melalui https://www.lmkn.id/lisensi/\\r\\nDemikian yang bisa kami informasikan, Semoga membantu.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(226,19,'pengajuan perubahan tempat cetak saat daftar online','Mohon maaf, saat ini kanwil tidak memiliki kewenangan untuk mengubah tempat cetak. ðŸ™ðŸ™ \\r\\nSaran kami kakak bisa mencetak sesuai dengan pemilihan tempat cetak sebelumnya ataupun kakak juga bisa mengajukan ulang pemilihan tempat cetak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(227,1,'pendaftaran merek','Untuk pendaftaran bisa melalui mandiri di Website merek.dgip.go.id dengan persyaratan sesuai dengan jenis permohonan.\\r\\nUntuk lebih jelasnya, jika ingin mendapatkan pelayanan tatap muka langsung, silahkan bisa ke Kantor Wilayah pada Hari Senin-Kamis Pukul 08.00-15.00 WIB ya kak.\\r\\nSemoga membantu',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(228,31,'berapa lama proses pengajuan magang','Terkait dengan pendaftaran magang, pengajuan yang kakak ajukan akan kami sampaikan kepada pimpinan kami. Proses approval membutuhkan kurang lebih 7 hari kerja kak. Nanti apabila sudah ada surat persetujuan akan kami sampaikan kepada kakak melalui pegawai pembimbing magang.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(229,1,'Perpanjang Merek','Syarat:\\r\\n 1. Etiket/Label Merek\\r\\n 2. Sertifikat Merek\\r\\n 3. Surat Kuasa Konsultan KI Bermaterai (jika menggunakan Konsultan)\\r\\n 4. Surat Pernyataan Penggunaan Merek (download contoh surat)\\r\\n 5. Surat Pernyataan Tidak Menggunakan Kelas Barang/Jasa (untuk multi kelas)\\r\\n 6. Surat Rekomendasi UKM Binaan atau Surat Keterangan UKM Binaan Dinas (Asli)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(230,1,'Pendaftaran Merek','*Pendaftaran Merek*\\r\\n\\r\\n*SYARAT PENDAFTARAN MEREK*\\r\\n1. KTP Pemohon\\r\\n2. Etiket / Logo Merek\\r\\n3. Tanda Tangan digital Pemohon\\r\\n4. Apabila Pemohon Badan Hukum dapat menyertakan :\\r\\na. Akta Pendirian Badan Hukum\\r\\nb. Akta Perubahan Badan Hukum terakhir\\r\\nc. KTP Direksi\\r\\nd. NPWP Badan Hukum\\r\\n\\r\\n5. Untuk Pemohon dari UMKM dapat menyertakan :\\r\\na. Surat Keterangan MKM ari Dinas terkait\\r\\nb. Surat Pernyatan UMKM Bermaterai 10.000\\r\\n(Download di: https://docs.google.com/document/d/1UbQDWsI2ESS0YY5Napblp5VvWLEwsmP5/ )\\r\\n\\r\\n* PROSEDUR PENDAFTARAN MEREK*\\r\\nProsedur Pendaftaran Merek dapat dibaca melalui brosur berikut :\\r\\nhttps://drive.google.com/file/d/1jTJ62fC1LvcNY4-16Q3FAzJ36udooBc3/view?usp=sharing\\r\\n\\r\\n*LANGKAH PENDAFTARAN MEREK*\\r\\n- Pendaftaran Merek Secara Mandiri\\r\\nPendaftaran Merek dapat dilakukan secaara mandiri melalui online pada website merek.dgip.go.id\\r\\nLengkapi syarat-syarat pendaftaran sesuai brosur diatas\\r\\n\\r\\n- Pendaftaran Melalui Kantor Wilayah\\r\\nKantor Wilayah membuka layanan konsultasi dan pendaftaran Merek, Kanwil berlaku sebagai konsultan KI juga akan memberikan informasi dan saran, terkait pendaftaran merek, sehingga meminimalisir terjadinya penolakan pendaftaran\\r\\nPelayanan Konsultasi dilayani pada Hari Senin - Kamis Pukul 08.00 - 15.00 WIB',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(231,31,'Penelitian','Kanwil Kemenkum DIY, membuka Layanan Penelitian/Observasi Bagi Akademisi maupun Masyarakat.\\r\\n\\r\\n- PROSEDUR PENGAJUAN PENELITIAN\\r\\nProsedur pengajuan Penelitian/Observasi di Kanwil Kemenkum DIY, sebagai berikut :\\r\\n1. Pemohon mengajukan Melalui Google Form https://s.id/penelitiankanwildiy\\r\\n2. Pemohon melampirkan dokumen pendukung pada Google Form tersebut\\r\\n3. Apabila telah disetujui, Kanwil Kemenkum DIY akan mengeluarkan Surat Izin Penelitian kepada Ybs beserta dengan Narahubung yang bisa dihubungi untuk proses Wawancara/Observasi.\\r\\n\\r\\n- SYARAT DOKUMEN\\r\\nUntuk Pengajuan Penelitian/Observasi, Kanwil Kemenkum DIY membutuhkan dokumen sebagai berikut :\\r\\n1. Surat Permohonan Penelitian\\r\\n2. Proposal Penelitian\\r\\n3. List Pertanyaan pada bidang yang ingin diteliti\\r\\n\\r\\n- CATATAN\\r\\nSehubungan dengan proses penyiapan data dan informasi yang dibutuhkan, Disarankan untuk pengajuan Penelitian/Observasi minimal 14 Hari sebelum Pelaksanaan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(232,31,'Pengaduan','Apabila Bapak/Ibu ingin menyampaikan Pengaduan Notaris secara resmi dan dapat dipantau prosesnya, silakan membuat pengaduan melalui website SIEMON pada tautan berikut:\\r\\n\\r\\nðŸ”— https://siemon.kemenkum.go.id/pengaduan\\r\\n\\r\\nSetelah Bapak/Ibu mengisi laporan pengaduan melalui SIEMON, sistem akan memberikan ID Pengaduan yang dapat digunakan untuk memantau atau menelusuri perkembangan laporan tersebut.\\r\\n\\r\\nSeluruh pengaduan yang masuk akan diproses oleh Majelis Pengawas Daerah (MPD) Notaris sesuai dengan wilayah kerja Notaris yang bersangkutan.\\r\\n\\r\\nAdapun ketentuan terkait mekanisme pengaduan adalah sebagai berikut:\\r\\nLaporan pengaduan masyarakat atas dugaan pelanggaran jabatan Notaris disampaikan kepada Majelis Pengawas Daerah (MPD) sesuai dengan kedudukan Notaris.\\r\\nPemeriksaan dilakukan secara berjenjang, mulai dari MPD, kemudian Majelis Pengawas Wilayah (MPW), hingga upaya hukum banding ke Majelis Pengawas Pusat (MPP) apabila diperlukan.\\r\\n\\r\\nTerima kasih atas perhatian dan kerja samanya.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(233,31,'Greetings','*Selamat Datang di Layanan Online Informasi/Pengaduan Kanwil Kementerian Hukum D.I. Yogyakarta!*\\r\\n\\r\\nSilakan lengkapi data Anda:\\r\\nNama:\\r\\nNIK Pemohon Informasi/No. Paspor (bagi WNA):\\r\\nAlamat:\\r\\nNo. Telpon:\\r\\nKategori: Permohonan Informasi/Konsultasi/Pengaduan (pilih salah satu)\\r\\nIsi Pertanyaan/Pengaduan:\\r\\n\\r\\nSetelah mengisi data di atas dan mengirimkannya, pesan Anda akan segera direspon oleh petugas pada hari Senin - Jumat, pukul 08.00-16.00 WIB.\\r\\n\\r\\nTerima kasih!\\r\\n\\r\\nSalam hangat,  \\r\\nTim PPID\\r\\n\\r\\n*Catatan: Pesan akan direspon jika data diisi lengkap*\\r\\n\\r\\n*Untuk berbicara dengan petugas, silakan menghubungi pesawat telepon di nomor 0274 378431*',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(234,7,'Apa itu Perseroan Perorangan (PP)','Perseroan Perorangan adalah badan hukum yang didirikan oleh satu orang untuk kegiatan usaha yang memenuhi kriteria Usaha Mikro dan Kecil (UMK). Ini adalah bentuk PT (Perseroan Terbatas) yang disederhanakan dan khusus untuk UMK.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(235,7,'Siapa yang dapat mendirikan Perseroan Perorangan?','Hanya satu orang Warga Negara Indonesia (WNI) yang cakap hukum (minimal berusia 18 tahun dan mampu melakukan perbuatan hukum) yang dapat mendirikan dan memiliki Perseroan Perorangan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(236,7,'Ganti Email','Mengenai Perubahan Alamat email Pemohon dapat mengajukan secara bersurat dengan  melampirkan : \\r\\n- Surat permohonan \\r\\n- Surat pernyataan Bermaterai 10.000\\r\\n- SK Pendirian & Surat Pernyataan pendirian \\r\\n\\r\\nDokumen dikirimkan ke Alamat :\\r\\nKementrian Hukum\\r\\nCq : Direktur Badan Usaha\\r\\nJl. HR. Rasuna Said Kav. 6-7, Kuningan,\\r\\nJakarta Selatan 12940\\r\\n\\r\\nPerihal : permohonan perubahan Email',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(237,19,'Apabila saya akan mencetak apostille 3x. Apakah saya mengisi jumlah dokumen 3.  Atau saya mengajukan permohonan sebanyak 3x?','Jika seperti itu,\\r\\nKami beritahukan bahwa Untuk dokumen asli, tidak bisa mencetak sertifikat apostille lebih dari 1 kali ya kak.\\r\\nKarena nanti sertifikatnya direkatkan pada dokumen.\\r\\n\\r\\nJika yang kakak ajukan adalah dokumen fotocopy, misalnya fotocopy Ijazah yang dilegalisir,  kakak punya FC Ijazah 3 lembar,. maka bisa diajukan apostille cetak 3 kali.\\r\\nKarena nanti masing-masing sertifikat akan ditempel/rekatkan pada fc ijazah tersebut.\\r\\n\\r\\nSertifikat tidak bisa diberikan tanpa ditempel pada dokumen aslinya. Karena secara hukum, sertifikat berlaku jika ditempelkan pada dokumennya ya kak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(238,19,'Apostille SKBM','Apabila yang diminta adalah SKBM asli (Bahasa Indonesia), maka dokumen tersebut bisa langsung diajukan untuk proses apostille.\\r\\n\\r\\nNamun, apabila yang dibutuhkan adalah SKBM dalam bahasa asing (hasil terjemahan), maka dokumen harus diterjemahkan terlebih dahulu oleh penerjemah tersumpah. Setelah itu, barulah hasil terjemahannya dapat diajukan untuk apostille.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(239,18,'Permohonan Pewarganegaraan','Terkait dengan Permohonan Pewarganegaraan informasi mengenai syarat, prosedur dapat dibaca pada link berikut kak :\\r\\nhttps://jogja.kemenkum.go.id/adm-hukum-umum/pewarganegaraan\\r\\n\\r\\nUntuk pengajuannya dapat secara online pada aplikasi berikut :\\r\\nhttps://pewarganegaraan.ahu.go.id/\\r\\n\\r\\nUntuk tutorial pengajuan melalui online dapat dibaca melalui :\\r\\nhttps://panduan.ahu.go.id/doku.php?id=pewarganegaraan_pasal_19',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(240,19,'pengajuan spesimen','untuk pengajuan spesimen, jika data pejabat tsb belum tersedia pada pangkalan data AHU, maka hal itu wajib diurus ya kak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(241,19,'SKBM legalisir','Untuk SKBM apabila muslim yang mengeluarkan dari Kanwil Kemenag dan untuk non muslim yang mengeluarkan dari Dukcapil. \\r\\n\\r\\nDan proses apostille tergantung dari ketentuan Kedubes negara tujuannya :\\r\\n\\r\\nApabila yang diminta adalah Dokumen SKBM Asli (Bahasa Indonesia) atau SKBM Terjemahan dari Penerjemah Tersumpah.\\r\\n\\r\\nJika yang dibutuhkan adalah yang Asli saja, maka bisa langsung di apostille kan\\r\\n\\r\\nJika yang dibutuhkan adalah adalah Hasil Terjemahan, maka bisa Diterjemahkan terlebih dahulu melalui penerjemah tersumpah, baru dokumen terjemahan dilakukan apostille.\\r\\n\\r\\nPada intinya, Apostille adalah proses memberikan kekuatan hukum pada Dokumen yang akan digunakan untuk keperluan diluar negeri. Sehingga Dokumen tersebut sah dan dikui secara internasional.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(242,19,'percepatan apostille','kalau diterima 1 hari bisa selesai kak, namun kembali lagi kami ingatkan bahwa, tim verifikator berada di Tim AHU Pusat, seluruh pengajuan percepatan akan dilihat dari urgensitasnya ya kak. Jika ditolak maka proses verifikasi seperti biasa 3 hari kerja.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(243,19,'Legalisasi','Berikut adalah prosedur lengkap pengurusan legalisasi dokumen publik (Non-Apostille) untuk digunakan di negara yang belum tergabung dalam Konvensi Apostille :\\r\\n\\r\\n1. Tahap Pertama: Legalisasi di Kementerian Hukum (Ditjen AHU)\\r\\nLegalisasi di Ditjen AHU adalah proses verifikasi tanda tangan pejabat dan cap resmi pada dokumen asli.\\r\\n\\r\\nProsedur:\\r\\n1. Akses laman ahu.go.id dan pilih layanan \\\"Legalisasi\\\" (bukan Apostille).\\r\\n2. Daftarkan akun atau login ke sistem AHU Online.\\r\\n3. Input data formulir elektronik, pilih negara tujuan (Non-Apostille), dan unggah dokumen yang sudah disahkan pejabat berwenang.\\r\\n4. Tunggu verifikasi dari petugas.\\r\\n5. Setelah disetujui, lakukan pembayaran sesuai kode bayar yang muncul.\\r\\n6. Datang ke loket pelayanan (Pusat atau Kantor Wilayah Kemenkumham terdekat) untuk Pencetakan/Pemasangan Stiker Legalisasi.\\r\\n7. Biaya: Rp50.000,- per dokumen (PNBP).\\r\\n8. Jangka Waktu: Verifikasi paling lama 1 (satu) hari kerja.\\r\\nAlur Legalisasi-AHU selengkapnya dapat diakses pada link berikut :\\r\\nhttps://layanan.ahu.go.id/ahu/layanan-produk/perdata/legalisasi\\r\\n\\r\\n\\r\\n2. Tahap Kedua: Legalisasi di Kementerian Luar Negeri (Kemlu)\\r\\nSetelah mendapatkan stiker dari Kemenkumham, dokumen wajib dilegalisasi oleh Kemlu agar diakui secara internasional.\\r\\n\\r\\nProsedur:\\r\\n1. Akses aplikasi STEMPEL ASLI melalui legalisasi.kemlu.go.id.\\r\\n2. Daftarkan akun dan login.\\r\\n3. Isi formulir permohonan dan unggah foto dokumen yang sudah ditempeli stiker Kemenkumham.\\r\\n4. Lakukan pembayaran setelah permohonan diverifikasi dan disetujui.\\r\\n5. Setelah menerima notifikasi pembayaran, datang ke loket Pelayanan Legalisasi Kemlu (Jakarta) untuk menyerahkan dokumen asli dan mengambil stiker legalisasi Kemlu.\\r\\n6. Biaya: Rp50.000,- per dokumen.\\r\\n7. Jangka Waktu: Umumnya 1-3 hari kerja untuk verifikasi online.\\r\\n\\r\\n3. Tahap Ketiga: Legalisasi di Kedutaan Negara TUjuan (Jakarta)\\r\\nTahap akhir adalah pengesahan (attestation) oleh perwakilan negara tujuan di Indonesia.\\r\\n\\r\\nProsedur:\\r\\n1. Datang langsung ke Kantor Kedutaan Besar Negara TUjuan di Jakarta (Jl. H.R. Rasuna Said Kav. X/6).\\r\\n2. Menyerahkan dokumen yang telah dilegalisasi oleh Kemenkumham dan Kemlu RI.\\r\\n3. Mengisi formulir yang disediakan di loket konsuler.\\r\\n4. Membayar biaya legalisasi di tempat.\\r\\n5. Petugas akan memberikan stempel/tanda tangan pengesahan dari pihak Kedutaan.\\r\\n6. Waktu Pelayanan Loket:\\r\\n7. Senin - Kamis: 08.30 – 11.00 (Penyerahan) & 13.00 – 15.00 (Pengambilan).\\r\\n8. Jumat: 08.30 – 11.00 (Penyerahan) & 14.00 – 15.00 (Pengambilan).\\r\\n9. Biaya: Sesuai dengan tarif konsuler yang berlaku di Kedutaan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(245,31,'perubahan email','Mengenai Perubahan Alamat email Pemohon dapat mengajukan secara bersurat dengan \\r\\nmelampirkan : Surat permohonan , Surat pernyataan Bermaterai 10.000 , Apabila telah melakukan \\r\\npendirian perseroan lampirkan SK Pendirian & Surat Pernyataan pendirian Dokumen dikirimkan\\r\\nke Alamat :\\r\\nKementrian Hukum\\r\\nCq : Direktur Badan Usaha\\r\\nJl. HR. Rasuna Said Kav. 6-7, Kuningan,\\r\\nJakarta Selatan 12940\\r\\nPerihal : permohonan perubahan Email\\r\\n\\r\\nUntuk Estimasi antara 1 Minggu - 3 Bulan dari pengajuan surat tersebut, tergantung antrian layanan.\\r\\n\\r\\nUntuk akun pada sistem AHU merupakan ranah dari Tim Pusat ya kak, jadi kami tidak bisa membantu untuk reset/ganti email secara langsung. Sehingga perlu pengajuan sesuai prosedur diatas.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(246,4,'apa itu desain industri','Desain Industri adalah kreasi tentang bentuk, konfigurasi, atau komposisi garis atau warna yang memberikan kesan estetis dan dapat diwujudkan dalam pola 3D atau 2D untuk menghasilkan produk atau komoditas industri.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(247,4,'berapa lama perlindungan desain industri','Masa perlindungan desain industri adalah 10 tahun sejak tanggal penerimaan. Pemegang hak memiliki hak eksklusif untuk melarang orang lain tanpa persetujuannya membuat, memakai, atau menjual produk terkait.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(248,4,'syarat daftar desain industri','Syarat pendaftaran meliputi: KTP pemilik, Surat Pernyataan Kepemilikan bermaterai 10.000, serta Deskripsi Desain Industri yang memuat gambar tampak depan, belakang, atas, bawah, samping, dan perspektif.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(249,4,'alur pendaftaran desain industri','Proses dimulai dari Permohonan, Pemeriksaan Administratif (3 bulan), Pengumuman (3 bulan), Pemeriksaan Substantif (6 bulan), hingga Pencetakan Sertifikat (2 bulan).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(250,4,'biaya daftar desain industri','*DAFTAR TARIF PNBP DESAIN INDUSTRI* (PP No. 45 Tahun 2024). 1. *UMKM*: Satu Desain (Rp250.000), Satu Set (Rp550.000). 2. *UMUM*: Satu Desain (Rp800.000), Satu Set (Rp1.250.000). Informasi lebih lanjut hubungi Kanwil Kemenkum DIY pada hari kerja.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(251,4,'kontak kanwil kemenkumham diy','Anda dapat menghubungi Kanwil Kemenkum DIY di Jl. Gedongkuning No. 146 Yogyakarta atau melalui telepon di 085 826 146 555.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(252,4,'Brosur Desain Industri','Berikut Brosur untuk Desain Industri :\\r\\nhttps://drive.google.com/file/d/1jVhMO83mnwrqIm7roqZcafZQQHj1SL5k/view?usp=sharing',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(253,1,'biaya daftar merek','*TARIF PENDAFTARAN MEREK*\\n(Sesuai PP No. 45 Tahun 2024)\\n\\n1. *USAHA MIKRO & KECIL (UMKM)*\\n- Per Kelas: Rp500.000\\n\\n2. *UMUM*\\n- Per Kelas: Rp1.800.000\\n\\n*Catatan:* Pembayaran dilakukan melalui sistem PNBP setelah mendapatkan kode billing[cite: 138, 139].',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(254,1,'biaya perpanjang merek','*TARIF PERPANJANGAN MEREK*\\r\\n(PP No. 45 Tahun 2024)\\r\\n\\r\\n*A. Dalam Jangka Waktu (6 Bulan sebelum/sampai berakhir):*\\r\\n- UMKM: Rp1.000.000 /kelas\\r\\n- UMUM: Rp2.250.000 /kelas\\r\\n\\r\\n*B. Masa Anugerah (Maks. 6 Bulan setelah berakhir):*\\r\\n- UMKM: Rp2.000.000 /kelas\\r\\n- UMUM: Rp4.500.000 /kelas',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(255,1,'proses pendaftaran merek','*ALUR PROSES PENDAFTARAN MEREK*\\r\\n\\r\\n1. *Pemeriksaan Formalitas:* 15 Hari \\r\\n2. *Pengumuman:* 2 Bulan \\r\\n3. *Pemeriksaan Substantif:* 150 Hari\\r\\n4. *Penerbitan Sertifikat:* Jika disetujui',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(256,1,'cek merek','Sebelum mendaftar, disarankan melakukan penelusuran mandiri melalui laman *pdaki-indonesia.dgip.go.id*. Hal ini penting untuk memastikan tidak ada merek yang sama atau mirip dengan merek yang akan Kakak ajukan guna meminimalisir risiko penolakan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(257,1,'apa itu kelas merek','*Kelas Barang/Jasa* adalah pengelompokan jenis bidang usaha (berdasarkan Klasifikasi Nice). Misalnya, Kelas 25 untuk Pakaian/Fashion, Kelas 43 untuk Jasa Restoran/Kuliner, atau Kelas 3 untuk Kosmetik. Biaya pendaftaran dihitung *per kelas* yang diajukan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(258,1,'biaya kembali jika ditolak','Sesuai aturan PNBP, biaya permohonan pendaftaran merek yang sudah dibayarkan ke kas negara *tidak dapat ditarik kembali* meskipun permohonan tersebut nantinya ditolak atau ditarik kembali oleh pemohon.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(259,1,'format logo merek','*Etiket atau Logo Merek* yang diunggah harus jelas (tidak pecah) dengan latar belakang polos. Disarankan menggunakan format file gambar (.jpg/.png) dengan resolusi yang baik agar detail merek terlihat jelas saat dicetak di sertifikat.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(260,1,'ubah nama atau alamat merek','Jika ada perubahan nama pemohon atau alamat pada merek yang sedang diproses atau sudah terdaftar, Kakak dapat mengajukan permohonan *Pencatatan Perubahan Nama dan/atau Alamat* melalui sistem online dengan membayar biaya PNBP sesuai ketentuan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(261,1,'keuntungan daftar di kanwil','Dengan berkonsultasi di *Kanwil Kemenkumham DIY*, Kakak akan dibantu oleh petugas untuk mengecek potensi kemiripan merek dan mendapatkan arahan pengisian kelas barang/jasa yang tepat, sehingga memperkecil peluang penolakan secara administratif maupun substantif.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(262,1,'cara cek kelas merek','Untuk pendaftaran merek, kategori kelas dibagi menjadi dua:\\r\\n1. *Kelas 1-34*: Diperuntukkan bagi jenis permohonan *Dagang* (Barang).\\r\\n2. *Kelas 35-45*: Diperuntukkan bagi jenis permohonan *Jasa*.\\r\\nPastikan Kakak memilih kelas yang sesuai dengan model bisnis yang dijalankan ya. \\r\\n\\r\\n Untuk mengetahui klasifikasi kelas merek secara keseluruhan dan mencari jenis barang/jasa yang tepat, Kakak dapat melakukan pengecekan secara mandiri melalui laman resmi berikut:\\r\\n\\r\\n*https://skm.dgip.go.id*\\r\\n\\r\\nSilakan masukkan kata kunci jenis produk Kakak di kolom pencarian pada laman tersebut.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(263,3,'syarat daftar hak cipta','*SYARAT PENCATATAN HAK CIPTA*\\n\\n1. KTP Pencipta / Pemegang Hak Cipta\\n2. Surat Pernyataan Ciptaan (Materai 10.000)\\n3. Contoh Ciptaan (File karya)\\n4. Manual Book & Source Code (Khusus Program Komputer/Software)\\n5. Surat Pengalihan Hak (Jika kepemilikan dialihkan)\\n6. *Jika UMKM:* Surat Keterangan UMKM Dinas terkait & Surat Pernyataan UMKM bermaterai.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(264,3,'alur pendaftaran hak cipta','*ALUR PERMOHONAN HAK CIPTA (POP HC)*\\n\\n1. Registrasi Akun di *e-hakcipta.dgip.go.id*\\n2. Pilih permohonan baru & isi formulir\\n3. Unggah dokumen pendukung & contoh ciptaan\\n4. Lakukan pembayaran PNBP\\n5. *Persetujuan Otomatis (POP HC)*: Sertifikat dapat langsung diunduh setelah pembayaran terverifikasi.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(265,3,'biaya daftar hak cipta','*TARIF PNBP PENCATATAN CIPTAAN*\\n(Berdasarkan PP No. 45 Tahun 2024)\\n\\n1. *USAHA MIKRO & KECIL (UMKM):*\\n- Umum: Rp200.000\\n- Program Komputer: Rp300.000\\n\\n2. *UMUM:*\\n- Umum: Rp400.000\\n- Program Komputer: Rp600.000',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(266,3,'masa perlindungan hak cipta','*MASA PERLINDUNGAN HAK CIPTA*\\n\\n- *Ciptaan (Buku, Musik, Seni Rupa, dll):* Seumur Hidup Pencipta + 70 Tahun setelah meninggal.\\n- *Program Komputer/Software:* 50 Tahun sejak pertama kali dipublikasikan.\\n- *Seni Terapan:* 25 Tahun sejak pertama kali dipublikasikan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(267,3,'Brosur Hak cipta','Silakan unduh brosur informasi lengkap mengenai Hak Cipta melalui tautan berikut:\\nhttps://drive.google.com/file/d/1jWdM1iU2i2js4Etyc9qYbgMzJg7ZQ1by/view?usp=sharing',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(268,3,'beda hak cipta dan merek','Sering tertukar? Ini bedanya:\\n- *Merek:* Melindungi *Nama/Logo* yang digunakan untuk jualan produk/jasa.\\n- *Hak Cipta:* Melindungi *Karya Kreatif* seperti buku, lagu, film, atau kode program.\\nContoh: Mereknya \\\"Disney\\\", Hak Ciptanya film \\\"Mickey Mouse\\\".',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(269,3,'berapa lama sertifikat hak cipta jadi','Dengan sistem *Persetujuan Otomatis Permohonan Hak Cipta (POP HC)*, sertifikat Kakak bisa terbit secara *real-time* (langsung jadi) sesaat setelah Kakak menyelesaikan pembayaran PNBP.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(270,3,'apakah wajib daftar hak cipta','Hak Cipta menganut prinsip *Deklaratif*, artinya perlindungan muncul otomatis sejak karya diwujudkan. Namun, *Pencatatan* di Kemenkumham sangat penting sebagai *alat bukti utama* jika suatu saat terjadi sengketa atau klaim dari pihak lain.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(271,3,'tempat konsultasi hak cipta jogja','Untuk konsultasi tatap muka di wilayah Yogyakarta, Kakak bisa datang ke *Kanwil Kemenkumham DIY*:\\r\\nSilahkan datang ke Kantor Kami :\\r\\nKantor Wilayah Kementerian Hukum Daerah Istimewa Yogyakarta\\r\\nJl. Gedongkuning No. 146 Rejowinangun, Kotagede, Yogyakarta, Daerah Istimewa Yogyakarta 55171\\r\\nTelpon: (0274) 378431 / Faksimili: (0274) 378432, 373195 / Whatsapp : 08112640146\\r\\nGoogle Maps : https://maps.app.goo.gl/1CngRpBy2HJY9B5r7\\r\\nJam Pelayanan: Senin-Kamis (08.00-15.00 WIB).\\r\\n',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(272,1,'kriteria umkm merek','*KRITERIA UMKM (Mikro & Kecil)*\\n\\nUntuk mendapatkan tarif PNBP UMKM (Rp500.000), usaha Kakak harus memenuhi kriteria berdasarkan Modal Usaha:\\n\\n1. *USAHA MIKRO:*\\n- Modal Usaha maksimal *Rp1 Miliar*.\\n- Hasil Penjualan Tahunan maksimal *Rp2 Miliar*.\\n\\n2. *USAHA KECIL:*\\n- Modal Usaha: *>Rp1 Miliar s/d Rp5 Miliar*.\\n- Hasil Penjualan Tahunan: *>Rp2 Miliar s/d Rp15 Miliar*.\\n\\nJika melebihi angka tersebut, maka masuk kategori *Usaha Menengah/Umum*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(273,1,'apa itu surat keterangan umkm','*Surat Keterangan UMKM* adalah dokumen wajib bagi pendaftar tarif khusus. Kakak bisa melampirkan:\\n1. Sertifikat NIB (Nomor Induk Berusaha).\\n2. Surat Keterangan dari Dinas Koperasi dan UKM setempat.\\n3. Surat Pernyataan UMKM bermaterai 10.000.\\n\\nDokumen ini harus diunggah saat proses pendaftaran di web *merek.dgip.go.id*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(274,1,'modal usaha umkm','Berdasarkan regulasi terbaru, penentuan kategori UMKM kini dilihat dari *Modal Usaha* (di luar tanah dan bangunan tempat usaha). \\n- Mikro: s/d 1 Miliar.\\n- Kecil: 1 s/d 5 Miliar.\\n- Menengah: 5 s/d 10 Miliar.\\nUntuk tarif murah pendaftaran Merek, pastikan usaha Kakak masuk kategori *Mikro atau Kecil*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(275,1,'Surat Rekomendasi UMKM','Pemohon pendaftaran merek mendapatkan fasilitas dalam mengajukan permohonan Pendaftaran Merek sebagai Usaha Mikro dan Usaha Kecil dengan biaya yang berbeda dengan biaya permohonan umum.\\r\\n\\r\\nAdapun persyaratan yang harus dipenuhi adalah Surat Keterangan atau Surat Rekomendasi sebagai usaha mikro dan usaha kecil yang diterbitkan oleh:\\r\\na. Kementerian Koperasi dan UKM; atau Kementerian Perindustrian; atau Kementerian Perdagangan; atau Kementerian Pariwisata dan Ekonomi Kreatif atau\\r\\nb. Dinas Koperasi dan UKM; Dinas Perindustrian dan Perdagangan; atau Dinas Pariwisata dan Ekonomi Kreatif\\r\\n\\r\\nDengan mencantumkan sebagai berikut :\\r\\n1. Nama, jabatan dan Unit organisasi dan yang menandatangani surat keterangan\\r\\n2. Nama Pemohon Pendaftaran Merek\\r\\n3. Alamat Pemohon Pendaftaran Merek\\r\\n\\r\\nSurat Rekomendasi atau Surat Keterangan berlaku untuk 1 (satu) merek dalam 1(satu) kali pengajuan yang ditandatangani pada tahun yang sama dengan pengajuan permohonan pendaftaran merek.\\r\\n\\r\\nContoh Surat Rkeomendasi atau Surat Keterangan UMKM dari Dinas :\\r\\nhttps://drive.google.com/file/d/1GlTGdxW_o6IvQfO0smt1tGxd9rA0uACY/view?usp=sharing',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(276,1,'Alur Bisnis Proses Pendaftaran Merek','Adapun Alur Bisnis Proses pendaftaran Merek dapat diakses melalui :\\r\\nhttps://www.dgip.go.id/uploads/menu_utama/photo/id/877c721227db196a87cf832b8dc2bf9d.jpg',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(277,1,'apa itu perpanjangan merek','*PERPANJANGAN PERLINDUNGAN MEREK*\\n\\nPerpanjangan Jangka Waktu Perlindungan Merek diperlukan bagi pemilik hak merek yang sudah mendapatkan sertifikat untuk memperpanjang waktu pelindungannya selama 10 tahun lagi.\\n\\n? *Waktu Pengajuan:* Dapat dilakukan mulai 6 bulan sebelum masa pelindungan berakhir.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(278,1,'syarat perpanjangan merek','*SYARAT PERPANJANGAN MEREK*\\n\\n1. Etiket/Label Merek\\n2. Sertifikat Merek\\n3. Surat Kuasa Konsultan KI (jika menggunakan jasa konsultan)\\n4. Surat Pernyataan Penggunaan Merek\\n5. Surat Pernyataan Tidak Menggunakan Kelas Barang/Jasa (untuk multi kelas)\\n6. Surat Rekomendasi/Keterangan UMK Binaan Dinas (Khusus kategori UMK)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(279,1,'biaya perpanjangan merek','*BIAYA PERPANJANGAN MEREK (Per Kelas)*\\n\\n1. *Masa 6 Bulan SEBELUM berakhir:*\\n- Umum: Rp2.250.000\\n- UMK: Rp1.000.000\\n\\n2. *Masa 6 Bulan SETELAH berakhir (Kadaluarsa):*\\n- Umum: Rp4.500.000\\n- UMK: Rp2.000.000\\n\\nSegera urus sebelum masa perlindungan habis untuk menghindari denda biaya 2x lipat!',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(280,1,'cara perpanjangan merek umkm','*PROSEDUR PERPANJANGAN MEREK (KATEGORI UMK)*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih *Pasca Permohonan Online* -> Klik *Tambah*\\n3. Pilih tipe: *Perpanjangan Jangka Waktu Perlindungan Merek*\\n4. Klik *Tambah Permohonan*, masukkan Nomor Permohonan, klik Simpan\\n5. Masukkan Data Pemohon & Dokumen Persyaratan\\n6. Cek Preview data, klik *Buat Billing*\\n7. Lakukan pembayaran (Otomatis tersubmit setelah bayar)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(281,1,'cara perpanjangan merek umum','*PROSEDUR PERPANJANGAN MEREK (KATEGORI UMUM)*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih *Pasca Persetujuan Otomatis Online* -> Klik *Tambah*\\n3. Pilih tipe permohonan sesuai sisa jangka waktu merek Anda\\n4. Klik *Tambah Permohonan*, masukkan Nomor Permohonan, klik Simpan\\n5. Masukkan Data Pemohon & Lampirkan Persyaratan\\n6. Cek Preview data, klik *Buat Billing*\\n7. Lakukan pembayaran (Otomatis tersubmit setelah bayar)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(282,1,'perpanjangan merek kadaluarsa','*PERPANJANGAN MEREK 6 BULAN KADALUARSA*\\n\\nJika perlindungan sudah habis (maksimal 6 bulan lewat), gunakan prosedur berikut:\\n1. Pilih menu Pasca Permohonan (UMK) atau Pasca Persetujuan Otomatis (Umum).\\n2. Pilih Tipe: *Perpanjangan Jangka Waktu Perlindungan Merek 6 Bulan Kadaluarsa*.\\n3. Ikuti langkah pengisian data seperti biasa.\\n4. Bayar billing sesuai tarif denda yang muncul.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(283,1,'apa itu keberatan merek','*PENGAJUAN KEBERATAN ATAS PERMOHONAN MEREK*\\n\\nLayanan ini digunakan apabila Anda merasa keberatan atas rencana pendaftaran merek pihak lain yang sedang dalam masa *Pengumuman* di Berita Resmi Merek.\\n\\nKeberatan Anda akan menjadi bahan pertimbangan Pemeriksa Merek untuk memutuskan apakah merek tersebut layak *Didaftar* atau *Ditolak*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(284,1,'syarat ajukan keberatan merek','*SYARAT PENGAJUAN KEBERATAN MEREK*\\n\\n1. Cover dan Isi Berita Resmi Merek (BRM) yang memuat merek yang dimaksud.\\n2. Surat Permohonan Keberatan/Sanggahan.\\n3. Surat Kuasa Konsultan KI bermaterai (jika menggunakan jasa Konsultan).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(285,1,'cara ajukan keberatan merek','*PROSEDUR PENGAJUAN KEBERATAN MEREK*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih menu *Pasca Permohonan Online* -> Klik *Tambah*\\n3. Pilih tipe permohonan: *Pengajuan keberatan atas permohonan merek*.\\n4. Klik *Tambah Permohonan*, masukkan Nomor Permohonan merek yang ingin Anda beratkan, klik Simpan.\\n5. Masukkan Data Pemohon & Lampirkan Dokumen Persyaratan.\\n6. Preview data, klik *Buat Billing*.\\n7. Lakukan pembayaran (Otomatis tersubmit setelah bayar).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(286,1,'biaya keberatan merek','*BIAYA PENGAJUAN KEBERATAN MEREK*\\n\\nBiaya PNBP untuk pengajuan keberatan adalah:\\n? *Rp1.000.000* per permohonan merek yang diajukan keberatan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(287,1,'apa itu banding merek','*PERMOHONAN BANDING MEREK*\\n\\nPermohonan Banding Merek diperlukan apabila Anda merasa keberatan atas *Surat Penolakan Tetap* dari DJKI atas permohonan merek yang Anda ajukan. \\n\\nPada tahapan ini, permohonan banding Anda akan diterima, diperiksa, dan diputuskan oleh *Komisi Banding Merek* yang bersifat independen.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(288,1,'syarat banding merek','*SYARAT PERMOHONAN BANDING MEREK*\\n\\n1. Surat Permohonan Banding Merek yang ditujukan kepada Komisi Banding Merek.\\n2. Surat Pemberitahuan Penolakan Definitif/Tetap.\\n3. Surat Kuasa (jika menggunakan jasa konsultan).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(289,1,'cara ajukan banding merek','*PROSEDUR PERMOHONAN BANDING MEREK*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih menu *Pasca Permohonan Online* -> Klik *Tambah*\\n3. Pilih tipe permohonan: *Permohonan Banding Merek*\\n4. Klik *Tambah Permohonan*, masukkan Nomor Permohonan Anda, lalu klik Simpan.\\n5. Masukkan Data Pemohon & Lampirkan Dokumen Persyaratan.\\n6. Preview data, klik *Buat Billing*.\\n7. Lakukan pembayaran (Otomatis tersubmit setelah bayar).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(290,1,'biaya banding merek','*BIAYA PERMOHONAN BANDING MEREK*\\n\\nBiaya PNBP untuk pengajuan banding adalah:\\n? *Rp3.000.000* per permohonan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(291,1,'apa itu perubahan nama alamat merek','*PENCATATAN PERUBAHAN NAMA/ALAMAT PEMILIK MEREK*\\n\\nLayanan ini diperlukan apabila terdapat perubahan nama atau alamat pemilik merek, baik saat permohonan masih dalam proses di DJKI maupun setelah sertifikat merek terbit.\\n\\nHal ini penting agar data pada pangkalan data KI tetap akurat dan sesuai dengan identitas terbaru pemilik hak.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(292,1,'syarat perubahan nama alamat merek','*SYARAT PERUBAHAN NAMA/ALAMAT MEREK*\\n\\n1. Bukti Perubahan Nama/Alamat (Misal: SK Kemenkumham, KTP Terbaru, atau Akta).\\n2. Formulir Perubahan Nama/Alamat.\\n3. Fotokopi KTP.\\n4. Sertifikat Merek (jika sudah terbit).\\n5. Surat Kuasa Konsultan KI bermaterai (jika menggunakan jasa konsultan).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(293,1,'cara ubah nama alamat merek','*PROSEDUR PERUBAHAN NAMA/ALAMAT MEREK*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih menu *Pasca Permohonan Online* -> Klik *Tambah*\\n3. Pilih tipe: *Pencatatan Perubahan Nama dan/atau Alamat Pemilik Merek*.\\n4. Klik *Tambah Permohonan*, masukkan Nomor Permohonan/Sertifikat, klik Simpan.\\n5. Masukkan Data Pemohon & Lampirkan Dokumen Persyaratan.\\n6. Preview data, klik *Buat Billing*.\\n7. Lakukan pembayaran (Otomatis tersubmit setelah bayar).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(294,1,'biaya ubah nama alamat merek','*BIAYA PERUBAHAN NAMA/ALAMAT MEREK*\\n\\nBiaya PNBP untuk pencatatan perubahan nama atau alamat adalah:\\n? *Rp300.000* per nomor permohonan atau nomor terdaftar.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(295,1,'apa itu pengalihan hak merek','*PENCATATAN PENGALIHAN HAK ATAS MEREK*\\n\\nLayanan ini diperlukan apabila hak atas merek beralih dari pemilik lama ke pemilik baru. Pengalihan ini bisa disebabkan karena:\\n1. Hibah\\n2. Pewarisan\\n3. Wasiat\\n4. Perjanjian/Kontrak\\n5. Penggabungan Badan Usaha (Merger)\\n\\nSangat penting untuk mencatatkan pengalihan ini agar pemilik baru memiliki legalitas penuh atas merek tersebut.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(296,1,'syarat pengalihan hak merek','*SYARAT PENGALIHAN HAK MEREK*\\r\\n\\r\\n1. Bukti Pengalihan Hak (Misal: Akta Jual Beli, Akta Hibah, atau Surat Perjanjian).\\r\\n2. Formulir Pengalihan Hak. Bisa didownload disini : https://dgip.go.id/unduhan/download/formulir-permohonan-pencatatan-pengalihan-hak-merek-42-2020\\r\\n3. Fotokopi KTP.\\r\\n4. Salinan Akta Badan Hukum (jika penerima/pemberi adalah badan hukum).\\r\\n5. Sertifikat Merek.\\r\\n6. Surat Kuasa Konsultan KI bermaterai (jika menggunakan jasa konsultan).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(297,1,'cara alihkan hak merek','*PROSEDUR PENGALIHAN HAK MEREK*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih menu *Pasca Permohonan Online* -> Klik *Tambah*\\n3. Pilih tipe: *Pencatatan Pengalihan Hak/Penggabungan (Merger) atas Merek/Merek Kolektif*.\\n4. Klik *Tambah Permohonan*, masukkan Nomor Permohonan/Sertifikat, klik Simpan.\\n5. Masukkan Data Pemohon (Penerima Hak) & Lampirkan Persyaratan.\\n6. Preview data, klik *Buat Billing*.\\n7. Lakukan pembayaran (Otomatis tersubmit setelah bayar).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(298,1,'biaya pengalihan hak merek','*BIAYA PENGALIHAN HAK MEREK*\\n\\nBiaya PNBP untuk pencatatan pengalihan hak adalah:\\n? *Rp700.000* per nomor permohonan atau nomor terdaftar.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(299,1,'apa itu lisensi merek','*PENCATATAN PERJANJIAN LISENSI MEREK*\\n\\nLisensi adalah izin yang diberikan oleh pemilik merek terdaftar kepada pihak lain melalui suatu perjanjian berdasarkan pada pemberian hak (bukan pengalihan hak) untuk menggunakan merek tersebut, baik untuk seluruh atau sebagian jenis barang/jasa.\\n\\nPencatatan lisensi ini bertujuan agar perjanjian tersebut memiliki akibat hukum terhadap pihak ketiga dan tercatat secara resmi di Pangkalan Data Kekayaan Intelektual.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(300,1,'syarat lisensi merek','*SYARAT PENCATATAN LISENSI MEREK*\\n\\n1. Bukti Perjanjian Lisensi.\\n2. Identitas Pemohon dan Penerima Lisensi (KTP/Paspor).\\n3. Salinan Sah Akta Pendirian Badan Hukum (jika badan hukum).\\n4. Sertifikat Merek.\\n5. Surat Kuasa Konsultan KI bermaterai (jika menggunakan jasa konsultan).\\n6. Surat Pernyataan Perjanjian Lisensi.\\n7. Surat Permohonan Pencatatan Lisensi.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(301,1,'cara urus lisensi merek','*PROSEDUR PENCATATAN LISENSI (POP ONLINE)*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih menu *Pasca Persetujuan Otomatis Online* -> Klik *Tambah*\\n3. Pilih tipe: *Pencatatan Perjanjian Lisensi*.\\n4. Masukkan Data Pemohon & Lampirkan Persyaratan.\\n5. Preview data, pastikan sudah benar.\\n6. Klik *Buat Billing*, lalu lakukan pembayaran.\\n7. Permohonan akan otomatis tersubmit setelah pembayaran terverifikasi.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(302,1,'biaya lisensi merek','*BIAYA PENCATATAN LISENSI MEREK*\\n\\nBiaya PNBP untuk pencatatan perjanjian lisensi adalah:\\n? *Rp1.000.000* per nomor terdaftar.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(303,1,'apa itu penghapusan merek','*PENCATATAN PENGHAPUSAN PENDAFTARAN MEREK*\\n\\nLayanan ini digunakan oleh pemilik merek yang ingin menghapus pendaftaran mereknya dari Daftar Umum Merek, baik untuk seluruh atau sebagian jenis barang/jasa yang terdaftar.\\n\\nPenghapusan ini bersifat permanen dan mengakibatkan perlindungan hukum atas merek tersebut berakhir.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(304,1,'syarat hapus merek','*SYARAT PENGHAPUSAN PENDAFTARAN MEREK*\\n\\n1. Sertifikat Merek.\\n2. Surat Permohonan Penghapusan Pendaftaran Merek/Indikasi Geografis.\\n3. Surat Kuasa Konsultan KI bermaterai (jika menggunakan jasa konsultan).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(305,1,'cara hapus merek terdaftar','*PROSEDUR PENGHAPUSAN PENDAFTARAN MEREK*\\n\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih menu *Pasca Permohonan Online* -> Klik *Tambah*\\n3. Pilih tipe: *Pencatatan Penghapusan Pendaftaran Merek*.\\n4. Klik *Tambah Permohonan*, masukkan Nomor Permohonan/Terdaftar, klik Simpan.\\n5. Masukkan Data Pemohon & Lampirkan Persyaratan.\\n6. Preview data, klik *Buat Billing*.\\n7. Lakukan pembayaran (Otomatis tersubmit setelah bayar).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(306,1,'biaya hapus merek','*BIAYA PENGHAPUSAN PENDAFTARAN MEREK*\\n\\nBiaya PNBP untuk pencatatan penghapusan pendaftaran merek adalah:\\n? *Rp200.000* per nomor terdaftar.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(307,1,'apa itu petikan resmi merek','*PERMOHONAN PETIKAN RESMI PENDAFTARAN MEREK*\\n\\nPetikan Resmi adalah salinan resmi dari daftar umum merek yang diterbitkan oleh DJKI. Dokumen ini biasanya diperlukan sebagai bukti legalitas tambahan atau untuk keperluan administratif/hukum tertentu.\\n\\nLayanan ini diproses melalui sistem *Persetujuan Otomatis Online (POP)* sehingga prosesnya lebih cepat.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(308,1,'cara urus petikan resmi merek','*PROSEDUR PETIKAN RESMI MEREK (POP)*\\n\\n*Syarat:*\\n1. Sertifikat Merek\\n2. Surat Kuasa (jika melalui konsultan)\\n\\n*Alur:* \\n1. Login ke *merek.dgip.go.id*\\n2. Pilih *Pasca Persetujuan Otomatis Online*\\n3. Pilih tipe: *Permohonan Petikan Resmi Pendaftaran Merek/Merek Kolektif/IG*\\n4. Isi data pemohon & unggah dokumen\\n5. Bayar billing Rp300.000/nomor terdaftar\\n6. Selesai (Otomatis tersubmit).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(309,1,'keterangan tertulis perpanjangan merek','*PERMOHONAN KETERANGAN TERTULIS PERPANJANGAN MEREK*\\n\\nLayanan ini digunakan untuk mendapatkan pernyataan tertulis resmi mengenai status perpanjangan jangka waktu perlindungan merek Kakak.\\n\\n*Biaya:* Rp200.000 / nomor terdaftar\\n*Prosedur:* \\n1. Login ke *merek.dgip.go.id*\\n2. Pilih *Pasca Permohonan Online*\\n3. Pilih tipe: *Permohonan Keterangan Tertulis Mengenai Perpanjangan Jangka Waktu Merek Terdaftar*\\n4. Klik Tambah, isi data pemohon, lampirkan syarat, dan bayar kode billing.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(310,1,'perbaikan data merek salah ketik','*PERBAIKAN DATA MEREK (KESALAHAN PEMOHON)*\\n\\nLayanan ini digunakan jika terdapat kesalahan input data oleh pemohon saat pendaftaran awal. \\n\\n*Syarat:*\\n1. Dokumen Pendukung (data yang benar).\\n2. Surat Kuasa (jika melalui konsultan).\\n\\n*Prosedur:*\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih *Pasca Permohonan Online*\\n3. Pilih tipe: *Perbaikan Data Permohonan Pendaftaran Merek Karena Kesalahan Pemohon*\\n4. Masukkan data & lampirkan syarat.\\n5. Bayar billing Rp200.000/permohonan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(311,1,'ubah data di sertifikat merek','*PERUBAHAN DATA PADA SERTIFIKAT MEREK*\\n\\nDigunakan untuk mengubah data yang tertera pada sertifikat merek, merek kolektif, atau Indikasi Geografis.\\n\\n*Syarat:*\\n1. Sertifikat Merek.\\n2. Fotokopi KTP.\\n3. Surat Kuasa (jika melalui konsultan).\\n\\n*Prosedur:*\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih *Pasca Permohonan Online*\\n3. Pilih tipe: *Perubahan Data Permohonan Pendaftaran Merek, Merek Kolektif atau Indikasi Geografis pada Sertifikat*\\n4. Masukkan data & bayar billing Rp300.000/permohonan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(312,1,'salinan bukti prioritas merek','*SALINAN BUKTI PRIORITAS PENDAFTARAN MEREK*\\n\\nLayanan untuk mendapatkan salinan bukti hak prioritas bagi pemohon merek.\\n\\n*Syarat:*\\n1. Etiket/Label Merek.\\n2. Sertifikat Merek.\\n3. Surat Permohonan.\\n4. Surat Kuasa (jika melalui konsultan).\\n\\n*Prosedur:*\\n1. Login ke *merek.dgip.go.id*\\n2. Pilih *Pasca Permohonan Online*\\n3. Pilih tipe: *Biaya Salinan Bukti Prioritas Permohonan Merek*\\n4. Masukkan data & bayar billing Rp300.000/nomor permohonan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(313,1,'pelaksanaan putusan pengadilan merek','*SURAT PERMOHONAN PELAKSANAAN PUTUSAN PENGADILAN*\\n\\n*Syarat:*\\n1. Surat Permohonan\\n2. Salinan Putusan Pengadilan (Wajib kirim berkas fisik ke Kantor DJKI)\\n3. Surat Kuasa (jika menggunakan Konsultan)\\n\\n*Prosedur:*\\n- Login ke *merek.dgip.go.id*\\n- Pilih *Pasca Permohonan Online*\\n- Tipe: *Surat Permohonan Pelaksanaan Putusan Pengadilan*\\n- Lengkapi data & unggah syarat.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(314,1,'tarik kembali permohonan merek','*PERMOHONAN PENARIKAN KEMBALI PERMOHONAN BARU*\\n\\n*Syarat:*\\n1. Surat Permohonan\\n2. Surat Kuasa (jika menggunakan Konsultan)\\n\\n*Prosedur:*\\n- Login ke *merek.dgip.go.id*\\n- Pilih *Pasca Permohonan Online*\\n- Tipe: *Permohonan Penarikan Kembali Permohonan Baru*\\n- Lengkapi data & klik Selesai.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(315,1,'tanggapan surat permintaan hki','*TANGGAPAN TERHADAP SURAT PERMINTAAN DARI KANTOR HKI*\\n\\n*Syarat:*\\n1. Surat Kuasa Konsultan KI\\n2. Bukti Prioritas Asli (Bermaterai & Segel Pos)\\n3. Dokumen Pendukung & KTP\\n4. Terjemahan Bukti Prioritas (Penerjemah Tersumpah)\\n\\n*Prosedur:* Pilih menu *Pasca Permohonan Online* dengan tipe permohonan yang sesuai.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(316,1,'kekurangan syarat administratif merek','*KEKURANGAN PERSYARATAN ADMINISTRATIF*\\n\\n*Syarat:*\\n1. Surat Pernyataan Kepemilikan\\n2. Bukti/Surat Keterangan UMK (untuk tarif UMK)\\n3. Dokumen pendukung lain sesuai permintaan kantor HKI\\n\\n*Prosedur:* Login ke *merek.dgip.go.id* -> *Pasca Permohonan Online* -> Pilih tipe permohonan *Kekurangan Persyaratan Administratif*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(317,1,'surat hearing merek','*SURAT HEARING*\\n\\n*Syarat:*\\n1. Surat Permohonan\\n2. Etiket/Label Merek & Sertifikat\\n3. Fotocopy KTP\\n\\n*Prosedur:* Pilih menu *Pasca Permohonan Online* -> Tipe: *Surat Hearing*. Masukkan Nomor Permohonan untuk melanjutkan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(318,1,'sanggahan keberatan merek','*SURAT SANGGAHAN ATAS KEBERATAN*\\n\\n*Syarat:*\\n1. Surat Sanggahan\\n2. Etiket/Label Merek & Sertifikat\\n3. Fotocopy KTP\\n\\n*Prosedur:* Digunakan untuk membalas keberatan/oposisi dari pihak lain. Pilih menu *Pasca Permohonan Online* -> Tipe: *Surat Sanggahan atas Keberatan*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(319,1,'cek status merek','*STATUS MEREK*\\n\\n*Syarat:*\\n1. Surat Permohonan\\n2. Etiket/Label Merek & KTP\\n\\n*Prosedur:* Login ke *merek.dgip.go.id* -> *Pasca Permohonan Online* -> Tipe: *Status Merek*. Masukkan nomor permohonan Anda.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(320,1,'pengalihan kuasa merek','*PENGALIHAN KUASA*\\n\\n*Syarat:*\\n1. Surat Kuasa Baru (Materai)\\n2. Surat Permohonan & Salinan Akta Badan Hukum\\n3. Dokumen Pendukung & E-tiket\\n\\n*Prosedur:* Pilih *Pasca Permohonan Online* -> Tipe: *Pengalihan Kuasa*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(321,1,'permohonan lainnya merek','*PERMOHONAN LAINNYA*\\n\\nDigunakan untuk keperluan yang tidak tercantum dalam kategori spesifik.\\n\\n*Syarat:* Surat Permohonan, Dokumen Pendukung, Sertifikat, KTP.\\n*Prosedur:* Pilih *Pasca Permohonan Online* -> Tipe: *Permohonan Lainnya*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(322,1,'hapus sebagian jenis barang merek','*PENARIKAN SEBAGIAN JENIS BARANG/JASA*\\n\\n*Syarat:*\\n1. Surat Permohonan (Wajib menjelaskan barang yang dihilangkan dan dipertahankan)\\n2. Dokumen Pendukung\\n\\n*Prosedur:* Pilih *Pasca Permohonan Online* -> Tipe: *Penarikan Sebagian Jenis Barang/Jasa Masih dalam Permohonan*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(323,1,'pindah akun merek','*PERMOHONAN PENGALIHAN AKUN*\\n\\n*Syarat:*\\n1. KTP Asli\\n2. Surat Permohonan Pengalihan Akun (Materai)\\n3. Surat Pernyataan Kepemilikan Merek (Materai Asli)\\n\\n*Prosedur:* Pilih *Pasca Permohonan Online* -> Tipe: *Permohonan Pengalihan Akun Pada Sistem Layanan Permohonan Merek*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(324,1,'biaya cetak sertifikat merek lama','*BIAYA JASA PENERBITAN SERTIFIKAT MEREK*\\n\\n*Catatan:* Hanya untuk permohonan sebelum 4 Juli 2014. Setelah tanggal tersebut, sertifikat sudah otomatis.\\n\\n*Biaya:* Rp100.000 / nomor pendaftaran\\n*Prosedur:* Login *merek.dgip.go.id* -> *Pasca Permohonan Online* -> Tipe: *Biaya Jasa Penerbitan Sertifikat Merek*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(325,1,'perbaikan sertifikat merek salah kantor','*PERBAIKAN SERTIFIKAT ATAS KESALAHAN KANTOR HKI*\\n\\nLayanan ini khusus jika kesalahan cetak berasal dari sistem/kantor (Bebas Biaya PNBP).\\n\\n*Syarat:* Surat Permohonan, Sertifikat yang salah, KTP.\\n*Prosedur:* Pilih *Pasca Permohonan Online* -> Tipe: *Permohonan Perbaikan Sertifikat atas Kesalahan Kantor HKI*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(326,1,'apa itu merek internasional madrid protocol','*PROSEDUR PERMOHONAN MEREK INTERNASIONAL (MADRID PROTOCOL)*\\n\\nPermohonan Internasional diajukan kepada Biro Internasional melalui Direktorat Jenderal Kekayaan Intelektual (DJKI). Permohonan ini memungkinkan pemilik merek untuk mendapatkan perlindungan di berbagai negara anggota Protokol Madrid hanya dengan satu permohonan.\\n\\n?? *Alur Proses:* https://www.dgip.go.id/uploads/menu_utama/photo/id/c4728c0bb0ff5258c1e74a8dc0fa776a.jpg',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(327,1,'syarat daftar merek internasional','*SYARAT PERMOHONAN MEREK INTERNASIONAL*\\n\\n*Syarat Subjek (Siapa yang boleh daftar):*\\n1. Warga Negara Indonesia (WNI).\\n2. Memiliki domisili/tempat kedudukan hukum di wilayah NKRI.\\n3. Memiliki kegiatan usaha industri atau komersial yang nyata di NKRI.\\n\\n*Syarat Objek (Apa yang didaftarkan):*\\nPengajuan Internasional hanya dapat dilakukan jika pemohon *telah memiliki Permohonan atau Pendaftaran Merek Nasional* di DJKI sebelumnya (sebagai merek dasar).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(328,1,'formulir merek internasional madrid','*DOKUMEN & FORMULIR MADRID PROTOCOL*\\n\\nPermohonan wajib menggunakan Bahasa Inggris. Berikut link formulir yang diperlukan:\\n\\n- *Formulir MM2 (Wajib):* https://s.id/form-mm2-madrid\\n- *Formulir MM17 (Khusus Uni Eropa):* https://s.id/form-mm17-madrid\\n- *Formulir MM18 (Khusus Amerika Serikat):* https://s.id/form-mm18-madrid\\n\\n*Panduan & Negara Tujuan:*\\n- Panduan Lengkap: https://s.id/panduan-madrid\\n- Daftar Negara Tujuan: https://s.id/negara-madrid\\n\\n_Setelah diisi, formulir diunggah saat mengajukan permohonan Madrid di sistem online._',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(329,1,'cara daftar merek internasional','*PROSEDUR PENDAFTARAN MEREK INTERNASIONAL*\\n\\n1. Pastikan Anda sudah memiliki merek yang terdaftar atau sedang dalam proses di DJKI (Indonesia).\\n2. Unduh dan isi *Formulir MM2* dalam Bahasa Inggris.\\n3. Login ke sistem permohonan merek DJKI.\\n4. Pilih menu permohonan Madrid.\\n5. Unggah formulir yang telah diisi dan lengkapi data yang diminta.\\n6. Lakukan pembayaran sesuai tagihan yang muncul.\\n\\nKonsultasikan pengajuan Anda ke *Kanwil Kemenkumham DIY* untuk memastikan kesiapan dokumen.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(330,3,'diagram alur hak cipta','*DIAGRAM ALUR PENDAFTARAN HAK CIPTA*\\n\\nUntuk memudahkan memahami proses pencatatan Hak Cipta, silakan cek diagram alur resmi melalui tautan gambar berikut:\\n\\n?? *Alur Proses 1:* https://dgip.go.id/uploads/menu_utama/photo/id/0d397522186ba1aac1c8438b9fb2d640.jpg\\n\\n?? *Alur Proses 2:* https://dgip.go.id/uploads/menu_utama/photo/id/478d54161c3fa91561bdb71914040b6b.png',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(331,3,'tahapan daftar hak cipta','*LANGKAH-LANGKAH PENCATATAN HAK CIPTA (POP HC)*\\n\\nBerdasarkan diagram alur, berikut ringkasannya:\\n1. *Registrasi Akun* di e-hakcipta.dgip.go.id.\\n2. *Input Data:* Pilih pengajuan pencatatan, isi formulir, dan unggah contoh ciptaan serta dokumen pendukung.\\n3. *Pembayaran:* Lakukan pembayaran sesuai kode billing PNBP.\\n4. *Verifikasi:* Sistem melakukan validasi otomatis.\\n5. *Sertifikat Terbit:* Surat Pencatatan Ciptaan dapat langsung diunduh (Persetujuan Otomatis).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(332,3,'pengalihan hak cipta','*PENCATATAN PENGALIHAN HAK CIPTA*\\n\\n*Prosedur:*\\n1. Login ke *hakcipta.dgip.go.id*\\n2. Pilih *Pasca Hak Cipta* -> *Permohonan Baru*\\n3. Pilih Jenis: *Permohonan Pencatatan Pengalihan Hak atas Ciptaan*\\n4. Masukkan Deskripsi & Nomor Permohonan Ciptaan\\n5. Unggah syarat & Bayar billing.\\n\\n*Syarat:* Surat Pemindahan Hak, Surat Perjanjian, Bukti Pengalihan, Fotocopy Surat Pencatatan, KTP, Akta Perusahaan (jika badan hukum).\\n*Biaya:* Rp200.000 /permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(333,3,'ubah nama alamat hak cipta','*PERUBAHAN NAMA & ALAMAT PENCIPTA/PEMEGANG*\\n\\n*Prosedur:* Login -> *Pasca Hak Cipta* -> *Permohonan Baru* -> Pilih Jenis: *Permohonan Perubahan Nama dan Alamat*.\\n\\n*Syarat:*\\n1. Surat Permohonan Perubahan\\n2. Bukti Pengalihan Nama/Alamat\\n3. Fotocopy Surat Pencatatan Ciptaan\\n4. KTP\\n\\n*Biaya:* Rp150.000 /permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(334,3,'petikan resmi hak cipta','*PERMOHONAN PETIKAN TIAP PENCATATAN CIPTAAN*\\n\\n*Prosedur:* Pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Permohonan Petikan Tiap Pencatatan Ciptaan*.\\n\\n*Syarat:* Surat Permohonan Petikan, KTP, Surat Kuasa (jika perlu).\\n*Biaya:* Rp150.000 /permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(335,3,'salinan sertifikat hak cipta','*PERMOHONAN SALINAN SURAT PENCATATAN CIPTAAN*\\n\\n*Prosedur:* Login -> *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Permohonan Salinan Surat Pencatatan Ciptaan*.\\n\\n*Syarat:* Surat Permohonan Salinan, KTP, Dokumen Pendukung.\\n*Biaya:* Rp150.000 /permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(336,3,'lisensi hak cipta','*PENCATATAN LISENSI ATAS CIPTAAN*\\n\\n*Prosedur:* Pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Pencatatan Lisensi atas Ciptaan*.\\n\\n*Syarat:* Surat Permohonan Lisensi, Bukti Lisensi, Fotocopy Surat Pencatatan, KTP, Akta Perusahaan (jika badan hukum).\\n*Biaya:* Rp200.000 /permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(337,3,'perbaikan data hak cipta','*PERBAIKAN DATA CIPTAAN (KESALAHAN PEMOHON)*\\n\\n*Prosedur:* Pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Permohonan Perbaikan Data Permohonan Pencatatan Ciptaan*.\\n\\n*Syarat:* Surat Permohonan & Bukti Perbaikan Data, KTP.\\n*Biaya:* Rp150.000 /permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(338,3,'koreksi sertifikat hak cipta salah pemohon','*KOREKSI SURAT PENCATATAN (KESALAHAN PEMOHON)*\\n\\n*Prosedur:* Pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Permohonan Koreksi Surat Pencatatan Ciptaan*.\\n\\n*Syarat:* Surat Permohonan Koreksi, KTP, Dokumen Pendukung.\\n*Biaya:* Rp150.000 /permohonan',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(339,3,'koreksi sertifikat hak cipta salah kantor','*KOREKSI SURAT ATAS KESALAHAN DJKI*\\n\\n*Catatan:* Layanan ini khusus jika kesalahan berasal dari pihak DJKI.\\n\\n*Prosedur:* Pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Koreksi Surat atas Kesalahan DJKI*.\\n\\n*Syarat:* Surat Permohonan Koreksi & KTP.\\n*Biaya:* Gratis (Tanpa PNBP)',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(340,3,'tanggapan kekurangan formalitas hak cipta','*TANGGAPAN SURAT KEKURANGAN FORMALITAS*\\n\\n*Prosedur:* Digunakan untuk melengkapi syarat yang diminta oleh DJKI. Pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Tanggapan Surat Kekurangan Formalitas*.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(341,3,'cek status hak cipta','*PERTANYAAN STATUS PERMOHONAN*\\n\\n*Prosedur:* Jika ingin mengetahui progres permohonan, pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Pertanyaan Status*.\\n\\n*Syarat:* Surat Permohonan Pernyataan Status & KTP.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(342,3,'perbaikan contoh ciptaan','*PERBAIKAN CONTOH CIPTAAN*\\n\\n*Prosedur:* Pilih menu *Pasca Hak Cipta* -> *Permohonan Baru* -> Jenis: *Perbaikan Contoh Ciptaan*.\\n\\n*Syarat:* Surat Permohonan & Bukti Ciptaan yang Sudah Diperbaiki, KTP.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(343,3,'download formulir hak cipta','*DAFTAR FORMULIR & FORMAT SURAT HAK CIPTA*\\n\\nSilakan unduh formulir sesuai kebutuhan Kakak melalui tautan resmi DJKI di bawah ini:\\n\\n1. *Surat Pernyataan UMK:* https://dgip.go.id/unduhan/download/3-surat-keterangan-umk-44-2021\\n2. *Surat Pengalihan Hak Cipta:* https://dgip.go.id/unduhan/download/1-surat-permohonan-pengalihan-hak-cipta-44-2021\\n3. *Surat Perubahan Nama & Alamat:* https://dgip.go.id/unduhan/download/2-surat-permohonan-perubahan-nama-dan-alamat-hak-cipta-44-2021\\n4. *Surat Permohonan Lisensi:* https://dgip.go.id/unduhan/download/formulir-permohonan-pencatatan-lisensi-44-2020\\n5. *Surat Perbaikan Data:* https://dgip.go.id/unduhan/download/7-surat-permohonan-perbaikan-data-44-2021\\n6. *Surat Koreksi Sertifikat:* https://dgip.go.id/unduhan/download/8-surat-permohonan-koreksi-surat-pencatatan-44-2021\\n7. *Surat Petikan Hak Cipta:* https://dgip.go.id/unduhan/download/4-surat-permohonan-petikan-hak-cipta-44-2021\\n8. *Surat Salinan Hak Cipta:* https://dgip.go.id/unduhan/download/5-surat-permohonan-salinan-hak-cipta-44-2021\\n9. *Surat Keterangan Tertulis:* https://dgip.go.id/unduhan/download/6-surat-permohonan-keterangan-tertulis-44-2021\\n10. *Tanggapan Kekurangan Syarat:* https://dgip.go.id/unduhan/download/9-surat-tanggapan-surat-kekurangan-formalitas-44-2021\\n11. *Surat Perbaikan Contoh Ciptaan:* https://dgip.go.id/unduhan/download/13-surat-permohonan-perbaikan-ciptaan-44-2021\\n12. *Surat Pertanyaan Status:* https://dgip.go.id/unduhan/download/12-surat-permohonan-pertanyaan-status-44-2021',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(344,3,'format surat pernyataan ciptaan','*SURAT PERNYATAAN CIPTAAN*\\n\\nSurat pernyataan ciptaan adalah dokumen wajib yang harus diunggah bermaterai Rp10.000.\\n\\n? *Download di sini:* https://dgip.go.id/unduhan/download/7-surat-permohonan-perbaikan-data-44-2021 (Silakan sesuaikan format di dalam folder unduhan tersebut).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(345,2,'syarat daftar paten','*SYARAT PENDAFTARAN PATEN*\\n\\n1. KTP Inventor / Pemegang Invensi\\n2. Surat Pernyataan Invensi oleh Inventor (Materai 10.000)\\n3. Dokumen *Drafting Paten* (Memuat: Deskripsi, Abstrak, Klaim, dan Gambar)\\n4. *Jika Badan Hukum:* Akta Pendirian & Perubahan Terakhir, SK Menkumham, KTP Direksi, NPWP Badan Hukum\\n5. *Jika UMKM:* Surat Keterangan UMKM Dinas terkait atau bukti binaan untuk lembaga pendidikan/litbang.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(346,2,'biaya daftar paten','*TARIF PNBP PENDAFTARAN PATEN*\\n(Berdasarkan PP No. 45 Tahun 2024)\\n\\n*A. PATEN BIASA*\\n- UMKM/Pendidikan/Litbang: Rp350.000\\n- Umum: Rp1.250.000\\n\\n*B. PATEN SEDERHANA*\\n- UMKM/Pendidikan/Litbang: Rp200.000\\n- Umum: Rp800.000\\n\\n*Catatan:* Biaya di atas adalah untuk permohonan, belum termasuk biaya pemeriksaan substantif.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(347,2,'biaya pemeriksaan substantif paten','*TARIF PEMERIKSAAN SUBSTANTIF PATEN*\\n\\n1. *Paten Biasa:*\\n- UMKM/Pendidikan/Litbang: Rp2.000.000\\n- Umum: Rp3.000.000\\n\\n2. *Paten Sederhana:*\\n- UMKM/Pendidikan/Litbang: Rp500.000\\n- Umum: Rp1.250.000',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(348,2,'alur paten biasa','*ALUR PENDAFTARAN PATEN BIASA*\\n\\n1. Permohonan -> Pemeriksaan Administratif (14 hari)\\n2. Masa Tunggu (18 bulan sejak tanggal penerimaan)\\n3. Pengumuman (6 bulan)\\n4. Pemeriksaan Substantif (36 bulan)\\n5. Keputusan (Diberi Paten atau Ditolak)\\n6. Sertifikat (2 bulan jika disetujui).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(349,2,'alur paten sederhana','*ALUR PENDAFTARAN PATEN SEDERHANA*\\n\\n1. Permohonan -> Pemeriksaan Administratif (14 hari)\\n2. Pengumuman (2 bulan)\\n3. Pemeriksaan Substantif (12 bulan)\\n4. Keputusan (Diberi Paten atau Ditolak)\\n5. Sertifikat (2 bulan jika disetujui).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(350,2,'beda paten biasa dan sederhana','*PERBEDAAN PATEN BIASA & SEDERHANA*\\n\\n- *Paten Biasa:* Untuk invensi baru, mengandung langkah inventif, dan dapat diterapkan di industri (Masa perlindungan 20 tahun).\\n- *Paten Sederhana:* Untuk pengembangan dari produk/proses yang sudah ada, memiliki kegunaan praktis karena bentuk, konfigurasi, atau konstruksinya (Masa perlindungan 10 tahun).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(351,2,'apa itu drafting paten','*DRAFTING PATEN*\\n\\nDrafting Paten adalah dokumen spesifikasi paten yang wajib ada. Terdiri dari:\\n- *Deskripsi:* Penjelasan teknis invensi.\\n- *Klaim:* Batasan perlindungan hukum yang diminta.\\n- *Abstrak:* Ringkasan invensi.\\n- *Gambar:* Skema teknis (jika ada).',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(352,2,'data dukung paten','*DATA DUKUNG PENDAFTARAN PATEN BARU*\\n\\nBerikut dokumen yang wajib disiapkan dan diunggah:\\n1. Deskripsi Paten (Bahasa Indonesia)\\n2. Klaim & Abstrak\\n3. Gambar Invensi (PDF) & Gambar Publikasi (JPG)\\n4. Surat Pernyataan Kepemilikan Invensi oleh Inventor\\n5. Surat Pengalihan Hak (jika inventor & pemohon berbeda)\\n6. Surat Kuasa (jika via konsultan)\\n7. Surat Keterangan UMK (untuk tarif khusus UMK)\\n8. SK Akta Pendirian (untuk lembaga pendidikan/litbang pemerintah)\\n\\n?? *Lihat Alur:* https://dgip.go.id/uploads/menu_utama/photo/id/4dbf1944e5e5510b87fddab5c6d5ac25.jpg',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(353,2,'diagram alur paten','*DIAGRAM ALUR PROSES PENDAFTARAN PATEN*\\n\\nSilakan cek diagram alur resmi untuk memahami tahapan teknis pendaftaran:\\n\\n? *Paten Biasa:* https://dgip.go.id/uploads/menu_utama/photo/id/084c68db4c5da29933b77f1695debd00.jpg\\n? *Paten Sederhana:* https://dgip.go.id/uploads/menu_utama/photo/id/05c36b0085bc29ed4c065244902862f7.jpg',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(354,2,'sop penyelesaian paten','*SOP PENYELESAIAN PERMOHONAN PATEN*\\n\\nBerikut adalah standar prosedur operasional untuk penyelesaian paten:\\n\\n? *Paten Sederhana:* https://dgip.go.id/uploads/menu_utama/photo/id/2e3436884948dcedd251af9d4ac6da12.jpg\\n? *Paten Biasa:* https://dgip.go.id/uploads/menu_utama/photo/id/e6625e273303e408ff0ab505310deef9.jpg\\n? *Paten oleh Pemerintah:* https://dgip.go.id/uploads/menu_utama/photo/id/a8e09201121ad5ac88c138b4986d688e.jpg',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(355,2,'video panduan paten','*PANDUAN VIDEO LAYANAN PATEN*\\n\\nUntuk memudahkan Kakak, silakan simak panduan video berikut:\\n\\n1. *Perpanjangan Waktu Pemenuhan Syarat:* https://youtu.be/eIT2fuF2kpU\\n2. *Perpanjangan Waktu 1 Bulan (Dokumen):* https://youtu.be/S22WgI5pGyM\\n3. *Amandemen Klaim (Menambah Jumlah):* https://youtu.be/bpQakA-KAlI',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(356,2,'cara ubah klaim paten','*AMANDEMEN KLAIM PATEN*\\n\\nPerubahan klaim dapat dilakukan dengan ketentuan:\\n1. *Tidak menambah jumlah klaim:* Dilakukan untuk memperbaiki redaksi tanpa mengubah esensi.\\n2. *Menambah jumlah klaim:* Memerlukan prosedur khusus dan akan mempengaruhi biaya pemeriksaan substantif.\\n\\nSimak panduan teknisnya di sini: https://youtu.be/bpQakA-KAlI',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(357,19,'apostille ktp tidak ada tanda tangan','Untuk dokumen KTP yang tidak memiliki tanda tangan pejabat, dokumen tersebut harus dilakukan *legalisasi di Notaris* terlebih dahulu. Saat pengisian data di aplikasi Apostille, masukkan data pejabat Notaris tersebut.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(358,19,'apostille ijazah madrasah non nip','Ijazah dari Madrasah yang Kepala Sekolahnya tidak memiliki NIP tetap bisa di-Apostille. Kakak dapat menggunakan data nama Kepala Sekolah tersebut sebagai data pejabat pada kolom pengisian aplikasi.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(359,19,'apostille dokumen laminating','Jika dokumen asli sudah dilaminating, *wajib dibuka* terlebih dahulu sebelum dibawa untuk pencetakan. Hal ini dikarenakan Sertifikat Apostille harus ditempel/direkatkan langsung pada dokumen asli tersebut.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(360,19,'apostille dokumen fotocopy','Dokumen Fotocopy bisa di-Apostille dengan syarat dokumen tersebut telah *dilegalisir oleh pejabat berwenang* (basah). Nantinya, Sertifikat Apostille akan ditempelkan pada lembar fotocopy yang sudah dilegalisir tersebut.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(361,19,'pengambilan sertifikat apostille bukan pemilik','Jika pengambilan Sertifikat Apostille diwakilkan oleh orang lain, maka wajib membawa:\\n1. Surat Kuasa bermaterai Rp10.000.\\n2. Fotocopy KTP pemberi kuasa.\\n3. KTP asli penerima kuasa.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(362,19,'surat kuasa apostille pemilik di luar negeri','Jika pemilik dokumen berada di luar negeri, Surat Kuasa untuk pengambilan di Indonesia harus dilegalisasi oleh *Kedutaan Besar Republik Indonesia (KBRI)* atau Konsulat Jenderal (KJRI) di negara tersebut.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(363,19,'penyebab penolakan apostille','*PENYEBAB UMUM PENOLAKAN APOSTILLE*\\n\\n1. *Kesalahan Tipe Dokumen:* Salah memilih jenis dokumen saat input.\\n2. *Data Pejabat:* Nama, Jabatan, atau Instansi tidak sesuai dengan fisik dokumen.\\n3. *Spesimen TTD:* Tanda tangan pejabat tidak cocok dengan pangkalan data AHU.\\n4. *Pejabat Pensiun:* Pejabat yang menandatangani sudah pensiun/meninggal dunia, namun tidak dilakukan legalisir ulang oleh pejabat yang aktif.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38'),(364,19,'batas waktu cetak apostille','Setelah pembayaran PNBP selesai (Status Voucher: *Sudah Dibayar*), tidak ada batas waktu kadaluwarsa untuk pencetakan. Namun, disarankan segera dicetak di tempat cetak yang telah dipilih agar dokumen dapat segera digunakan.',1,0,NULL,NULL,'2026-05-09 18:33:38','2026-05-09 18:33:38');
